-- mio-ui: the Mio hub menu framework. Generated by tools/uilib; do not edit by hand.
-- Each entry is one module's source, keyed by the id the hub requires it by.
return {
	Format = 1;
	Host = 1;
	Modules = {
		["ui/appearance.lua"] = [[
-- Applies the hub-wide appearance preferences (background, motion, scale, density) on top of the
-- brand theme. `Base` is the untouched theme, so switching back to a preset restores it exactly.

-- Constants
local PRESETS = {
	Midnight = {
		background = Color3.fromRGB( 13, 15, 22 ); panel = Color3.fromRGB( 13, 15, 22 ); rail = Color3.fromRGB( 10, 12, 18 ); titleBar = Color3.fromRGB( 13, 15, 22 );
		surface = Color3.fromRGB( 17, 20, 29 ); surfaceAlt = Color3.fromRGB( 21, 25, 35 ); overlay = Color3.fromRGB( 27, 32, 44 ); elevated = Color3.fromRGB( 19, 23, 33 );
		control = Color3.fromRGB( 22, 26, 37 ); controlHover = Color3.fromRGB( 30, 35, 48 ); stroke = Color3.fromRGB( 38, 44, 60 ); strokeFaint = Color3.fromRGB( 28, 33, 45 );
	};
	Graphite = {
		background = Color3.fromRGB( 24, 24, 24 ); panel = Color3.fromRGB( 24, 24, 24 ); rail = Color3.fromRGB( 20, 20, 20 ); titleBar = Color3.fromRGB( 24, 24, 24 );
		surface = Color3.fromRGB( 30, 30, 30 ); surfaceAlt = Color3.fromRGB( 35, 35, 35 ); overlay = Color3.fromRGB( 44, 44, 44 ); elevated = Color3.fromRGB( 33, 33, 33 );
		control = Color3.fromRGB( 38, 38, 38 ); controlHover = Color3.fromRGB( 48, 48, 48 ); stroke = Color3.fromRGB( 56, 56, 56 ); strokeFaint = Color3.fromRGB( 44, 44, 44 );
	};

};

-- Main
local Appearance = { };

function Appearance.apply( Theme: any, Base: any, Preferences: any )
	for Key in PRESETS.Midnight do
		Theme[ Key ] = Base[ Key ];
	end

	for Key, Value in PRESETS[ Preferences.BackgroundStyle ] or { } do
		Theme[ Key ] = Value;
	end

	for _, Key in { "fast", "normal", "slow" } do
		Theme[ Key ] = Preferences.ReducedMotion and 0 or Base[ Key ];
	end

	local Scale = tonumber( Preferences.MenuScale ) or 1;

	if ( Scale ~= Scale or math.abs( Scale ) == math.huge ) then
		Scale = 1;
	end

	Theme.menuScale = math.clamp( Scale, 0.75, 1.25 );

	-- Touch always gets the tall rows; otherwise the Density preference picks them.
	Theme.rowHeight = ( Theme.touch and Base.rowHeightTouch ) or ( Preferences.Density == "Compact" and Base.rowHeightCompact ) or Base.rowHeight;
end

return Appearance;]];
		["ui/components/button.lua"] = [[
local P = require("ui/primitives.lua")
local Runtime = require("core/runtime.lua")
local Icons = require("ui/icons.lua")
local Common = require("ui/components/common.lua")

local BUTTON_HEIGHT = 22
local BUTTON_ICON_SIZE = 11

local function inferIcon(label: string): string?
	local lower = string.lower(label)
	if string.find(lower, "tp") or string.find(lower, "teleport") then
		return "map-pin"
	end
	if string.find(lower, "shoot") then
		return "crosshair"
	end
	if string.find(lower, "kill") then
		return "swords"
	end
	if string.find(lower, "refresh") then
		return "refresh-cw"
	end
	if string.find(lower, "view") or string.find(lower, "spectate") then
		return "eye"
	end
	if string.find(lower, "cancel") or string.find(lower, "leave") then
		return "x"
	end
	if string.find(lower, "join") then
		return "log-in"
	end
	if string.find(lower, "redeem") then
		return "ticket"
	end
	if string.find(lower, "activate") or string.find(lower, "apply") then
		return "zap"
	end
	if string.find(lower, "reset") then
		return "refresh-cw"
	end
	if string.find(lower, "set") then
		return "check"
	end
	if string.find(lower, "get") or string.find(lower, "unlock") then
		return "package"
	end
	if string.find(lower, "fling") then
		return "send"
	end
	return nil
end

return function(section: Instance, spec, ctx)
	local theme = ctx.theme
	local variant = spec.variant or "secondary"
	local labelText = spec.label or spec.text or "Run"
	-- Same height as the other controls; touch keeps a thumb-sized target.
	local Height = theme.touch and 32 or BUTTON_HEIGHT

	local holder = P.create("Frame", {
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, Height),
		Parent = section,
	})
	-- Line up with the rows' 6 px side padding; a button grid pads itself, and `inset = false` is for a
	-- button placed in a host that is already aligned.
	if spec.inset ~= false and not section:FindFirstChildOfClass("UIGridLayout") then
		P.paddingXY(holder, 6, 0)
	end

	-- Primary buttons carry the accent fill; everything else is a quiet control-coloured button.
	local Primary = variant == "primary"
	local function baseColor()
		return Primary and theme.accent or (theme.control or theme.surface)
	end
	local function hoverColor()
		return Primary and theme.accentBright or (theme.controlHover or theme.overlay)
	end

	local btn = Common.clickable(holder, theme, {
		maid = ctx.maid,
		getBaseColor = baseColor,
		getHoverColor = hoverColor,
		getHoverStrokeColor = function()
			return theme.textFaint
		end,
	})
	btn.Size = UDim2.fromScale(1, 1)
	btn.BackgroundTransparency = 0

	local row = P.create("Frame", {
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		Parent = btn,
	})
	P.listLayout(row, 6, Enum.FillDirection.Horizontal)
	local rowLayout = row:FindFirstChildOfClass("UIListLayout")
	if rowLayout then
		rowLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center
		rowLayout.VerticalAlignment = Enum.VerticalAlignment.Center
	end

	local iconName = if typeof(spec.icon) == "string" and spec.icon ~= "" then spec.icon else inferIcon(labelText)
	local icon = nil
	if iconName then
		icon = Icons.mount(row, iconName, {
			size = BUTTON_ICON_SIZE,
			color = Primary and theme.background or theme.textDim,
		})
	end

	local label = P.label(row, labelText, {
		Theme = theme,
		AutomaticSize = Enum.AutomaticSize.XY,
		Size = UDim2.fromOffset(0, Height),
		TextXAlignment = Enum.TextXAlignment.Center,
		Font = theme.fontMedium,
		TextColor3 = Primary and theme.background or theme.text,
		TextSize = theme.textSizeSmall,
		TextTruncate = Enum.TextTruncate.AtEnd,
	})
	local LabelBounds = P.create( "UISizeConstraint", { Parent = label } );
	local function RefreshLabelBounds( )
		local Reserved = 20;
		if ( icon ) then
			Reserved += BUTTON_ICON_SIZE + 6;
		end
		LabelBounds.MaxSize = Vector2.new( math.max( 0, row.AbsoluteSize.X - Reserved ), Height );
	end
	Common.connect( ctx, row : GetPropertyChangedSignal( "AbsoluteSize" ), RefreshLabelBounds );
	RefreshLabelBounds( );
	if spec.getLabel then
		local resolved = Common.safeCall(ctx, "button getLabel", spec.getLabel)
		if resolved ~= nil then
			label.Text = tostring(resolved)
		end
	end

	Common.onTheme(ctx, function()
		btn.BackgroundColor3 = baseColor()
		Icons.setColor(icon, Primary and theme.background or theme.textDim)
		label.TextColor3 = Primary and theme.background or theme.text
	end)

	local busy = false
	Common.connect(ctx, btn.MouseButton1Click, function()
		if busy then
			return
		end
		busy = true
		Common.defer(ctx, "button onClick " .. tostring(spec.label or spec.id or "Run"), function()
			if spec.canClick and not Common.safeCall(ctx, "button canClick", spec.canClick) then
				busy = false
				return
			end
			local fn = spec.onClick or spec.callback
			if typeof(fn) == "function" then
				Common.safeCall(ctx, "button onClick " .. tostring(spec.label or spec.id or "Run"), fn)
			end
			if spec.getLabel then
				local resolved = Common.safeCall(ctx, "button getLabel", spec.getLabel)
				if resolved ~= nil then
					label.Text = tostring(resolved)
				end
			end
			busy = false
		end)
	end)

	return {
		getText = function(): string
			return label.Text
		end,
		setText = function(t: string)
			Runtime.deferClient(function()
				if label.Parent then
					label.Text = tostring(t)
				end
			end)
		end,
	}
end]];
		["ui/components/colorpicker.lua"] = [[
local Services = require("core/services.lua")
local Util = require("core/util.lua")
local Theme = require("ui/theme.lua")
local P = require("ui/primitives.lua")
local Common = require("ui/components/common.lua")

local UserInputService = Services.UserInputService

return function(section: Instance, spec, ctx)
	local theme = ctx.theme
	local key = spec.key

	local defaultColor = if typeof(spec.default) == "Color3" then spec.default else theme.accent
	local color = ctx.config[key]
	if typeof(color) ~= "Color3" then
		color = defaultColor
		ctx.config[key] = color
	end
	local h, s, v = color:ToHSV()

	local root = P.create("Frame", {
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, theme.rowHeight),
		AutomaticSize = Enum.AutomaticSize.Y,
		Parent = section,
	})
	P.listLayout(root, theme.controlGap or 8)

	local header = P.create("Frame", {
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, theme.rowHeight),
		Parent = root,
	})
	P.paddingXY(header, 6, 0)
	P.label(header, spec.label or key, {
		Theme = theme,
		Size = UDim2.new(1, -40, 1, 0),
		TextColor3 = theme.textDim,
		Font = theme.fontMedium,
		TextSize = theme.textSize - 1,
	})
	local swatchBtn = P.create("TextButton", {
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, 0, 0.5, 0),
		Size = UDim2.fromOffset(26, 12),
		BackgroundColor3 = color,
		Text = "",
		AutoButtonColor = false,
		Parent = header,
	}) :: TextButton
	P.corner(swatchBtn, theme.cornerSmall)
	local swatchStroke = P.stroke(swatchBtn, theme.outline or theme.strokeBright, 1, 0)

	local panel = P.create("Frame", {
		BackgroundColor3 = theme.surfaceAlt,
		Size = UDim2.new(1, 0, 0, 144),
		Visible = false,
		Parent = root,
	})
	P.corner(panel, theme.cornerSmall)
	local panelStroke = P.stroke(panel, theme.strokeBright, 1, 0.34)
	P.padding(panel, 10)

	local svBox = P.create("Frame", {
		Size = UDim2.new(1, -30, 0, 98),
		BackgroundColor3 = Color3.fromHSV(h, 1, 1),
		Parent = panel,
	})
	P.corner(svBox, theme.cornerSmall)
	P.create("UIGradient", {
		Color = ColorSequence.new(Color3.new(1, 1, 1), Color3.new(1, 1, 1)),
		Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0),
			NumberSequenceKeypoint.new(1, 1),
		}),
		Parent = svBox,
	})
	local blackOverlay = P.create("Frame", {
		Size = UDim2.fromScale(1, 1),
		BackgroundColor3 = Color3.new(0, 0, 0),
		BackgroundTransparency = 0,
		Parent = svBox,
	})
	P.corner(blackOverlay, 4)
	P.create("UIGradient", {
		Rotation = 90,
		Color = ColorSequence.new(Color3.new(0, 0, 0), Color3.new(0, 0, 0)),
		Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 1),
			NumberSequenceKeypoint.new(1, 0),
		}),
		Parent = blackOverlay,
	})
	local svCursor = P.create("Frame", {
		Size = UDim2.fromOffset(8, 8),
		AnchorPoint = Vector2.new(0.5, 0.5),
		BackgroundColor3 = Color3.new(1, 1, 1),
		Parent = blackOverlay,
	})
	P.corner(svCursor, 4)
	P.stroke(svCursor, Color3.new(0, 0, 0), 1)

	local hueBar = P.create("Frame", {
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, 0, 0, 0),
		Size = UDim2.fromOffset(20, 98),
		Parent = panel,
	}) :: Frame
	P.corner(hueBar, theme.cornerSmall)
	P.create("UIGradient", {
		Rotation = 90,
		Color = ColorSequence.new({
			ColorSequenceKeypoint.new(0, Color3.fromHSV(0, 1, 1)),
			ColorSequenceKeypoint.new(0.17, Color3.fromHSV(0.17, 1, 1)),
			ColorSequenceKeypoint.new(0.33, Color3.fromHSV(0.33, 1, 1)),
			ColorSequenceKeypoint.new(0.5, Color3.fromHSV(0.5, 1, 1)),
			ColorSequenceKeypoint.new(0.67, Color3.fromHSV(0.67, 1, 1)),
			ColorSequenceKeypoint.new(0.83, Color3.fromHSV(0.83, 1, 1)),
			ColorSequenceKeypoint.new(1, Color3.fromHSV(1, 1, 1)),
		}),
		Parent = hueBar,
	})
	local hueCursor = P.create("Frame", {
		Size = UDim2.new(1, 4, 0, 3),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0),
		BackgroundColor3 = Color3.new(1, 1, 1),
		Parent = hueBar,
	})
	P.stroke(hueCursor, Color3.new(0, 0, 0), 1)

	local presetRow = P.create("Frame", {
		Size = UDim2.new(1, 0, 0, 18),
		Position = UDim2.new(0, 0, 0, 104),
		BackgroundTransparency = 1,
		Parent = panel,
	})
	P.listLayout(presetRow, 5, Enum.FillDirection.Horizontal)

	local control = {}
	local presetStrokes = {}

	local function applyToConfig(fire: boolean)
		color = Color3.fromHSV(h, s, v)
		ctx.config[key] = color
		swatchBtn.BackgroundColor3 = color
		svBox.BackgroundColor3 = Color3.fromHSV(h, 1, 1)
		svCursor.Position = UDim2.fromScale(s, 1 - v)
		hueCursor.Position = UDim2.fromScale(0.5, h)
		if fire then
			if spec.onChange then
				Common.safeCall(ctx, "color onChange " .. tostring(key), spec.onChange, color)
			end
			ctx.dispatch(key, color, "color")
		end
	end

	function control.set(c: Color3, silent: boolean?)
		if typeof(c) ~= "Color3" then
			c = defaultColor
		end
		local previous = color
		h, s, v = c:ToHSV()
		applyToConfig(not silent and c ~= previous)
	end
	function control.get(): Color3
		return color
	end
	control.setValue = control.set
	control.getValue = control.get

	for _, preset in (spec.presets or Theme.colorPresets) do
		local pv = typeof(preset) == "table" and preset.value or preset
		if typeof(pv) ~= "Color3" then
			continue
		end
		local b = P.create("TextButton", {
			Size = UDim2.fromOffset(18, 18),
			BackgroundColor3 = pv,
			Text = "",
			AutoButtonColor = false,
			Parent = presetRow,
		}) :: TextButton
		P.corner(b, theme.cornerSmall)
		local presetStroke = P.stroke(b, theme.stroke, 1, 0.45)
		table.insert(presetStrokes, presetStroke)
		Common.connect(ctx, b.MouseButton1Click, function()
			control.set(pv)
		end)
	end

	local activeSVInput: InputObject? = nil
	local activeHueInput: InputObject? = nil
	local function updateSV(px: number, py: number)
		local pos = svBox.AbsolutePosition
		local size = svBox.AbsoluteSize
		s = Util.clamp((px - pos.X) / math.max(size.X, 1), 0, 1)
		v = 1 - Util.clamp((py - pos.Y) / math.max(size.Y, 1), 0, 1)
		applyToConfig(true)
	end
	local function updateHue(py: number)
		local pos = hueBar.AbsolutePosition
		local size = hueBar.AbsoluteSize
		h = Util.clamp((py - pos.Y) / math.max(size.Y, 1), 0, 1)
		applyToConfig(true)
	end

	Common.connect(ctx, svBox.InputBegan, function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			if activeSVInput or activeHueInput then return end
			activeSVInput = input
			activeHueInput = nil
			updateSV(input.Position.X, input.Position.Y)
		end
	end)
	Common.connect(ctx, hueBar.InputBegan, function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			if activeSVInput or activeHueInput then return end
			activeHueInput = input
			activeSVInput = nil
			updateHue(input.Position.Y)
		end
	end)
	ctx.maid:give(UserInputService.InputChanged:Connect(function(input)
		if activeSVInput and ((activeSVInput.UserInputType == Enum.UserInputType.Touch and input == activeSVInput)
			or (activeSVInput.UserInputType ~= Enum.UserInputType.Touch and input.UserInputType == Enum.UserInputType.MouseMovement)) then
			updateSV(input.Position.X, input.Position.Y)
		elseif activeHueInput and ((activeHueInput.UserInputType == Enum.UserInputType.Touch and input == activeHueInput)
			or (activeHueInput.UserInputType ~= Enum.UserInputType.Touch and input.UserInputType == Enum.UserInputType.MouseMovement)) then
			updateHue(input.Position.Y)
		end
	end))
	ctx.maid:give(UserInputService.InputEnded:Connect(function(input)
		if input == activeSVInput then
			activeSVInput = nil
		end
		if input == activeHueInput then
			activeHueInput = nil
		end
	end))

	local open = false
	Common.connect(ctx, swatchBtn.MouseButton1Click, function()
		open = not open
		panel.Visible = open
	end)

	Common.onTheme(ctx, function()
		swatchStroke.Color = theme.outline or theme.strokeBright
		panel.BackgroundColor3 = theme.surfaceAlt
		panelStroke.Color = theme.strokeBright
		for _, stroke in presetStrokes do
			if stroke.Parent then
				stroke.Color = theme.stroke
			end
		end
	end)

	applyToConfig(false)
	return control
end]];
		["ui/components/common.lua"] = [[
-- Shared helpers for the menu components: guarded callbacks, maid-tracked connections, theme
-- listeners, and the standard row / field / clickable building blocks.

-- Dependencies
local P = require( "ui/primitives.lua" );
local Runtime = require( "core/runtime.lua" );

-- Main
local Common = { };

function Common.warn( Context: any, ... )
	if ( Context and typeof( Context.warn ) == "function" ) then
		Context.warn( ... );
		return;
	end

	warn( "[Hub][UI]", ... );
end

function Common.safeCall( Context: any, Label: string, Callback: any, ... ): any
	if ( typeof( Callback ) ~= "function" ) then
		return nil;
	end

	local Ok, Result = pcall( Callback, ... );

	if ( not Ok ) then
		Common.warn( Context, Label, "->", Result );
		return nil;
	end

	return Result;
end

function Common.defer( Context: any, Label: string, Callback: ( ) -> ( ) ): any
	local Connection = Runtime.deferClient( function( )
		Common.safeCall( Context, Label, Callback );
	end );

	if ( Connection and Context and Context.maid ) then
		Context.maid : give( Connection );
	end

	return Connection;
end

function Common.connect( Context: any, Signal: RBXScriptSignal, Callback: ( ...any ) -> ( ) ): RBXScriptConnection
	local Connection = Signal : Connect( Callback );

	if ( Context and Context.maid ) then
		Context.maid : give( Connection );
	end

	return Connection;
end

function Common.onTheme( Context: any, Callback: any ): any
	if ( Context and typeof( Context.onTheme ) == "function" and typeof( Callback ) == "function" ) then
		return Context.onTheme( Callback );
	end

	return nil;
end

-- A label-left / control-right row. Rows built at the theme's row height are remembered on the
-- theme so a density change can resize them in place (see Common.resizeRows).
function Common.row( Parent: Instance, Theme: any, Text: string, Height: number?, ControlWidth: number? ): ( Frame, TextLabel )
	local Reserve = ( ControlWidth or 72 ) + 12;
	local Row = P.create( "Frame", {
		BackgroundColor3 = Theme.overlay;
		BackgroundTransparency = 1;
		Size = UDim2.new( 1, 0, 0, Height or Theme.rowHeight );
		Parent = Parent;
	} ) :: Frame;
	P.corner( Row, Theme.cornerSmall );
	P.paddingXY( Row, 6, 0 );

	local Label = P.label( Row, Text, {
		Theme = Theme;
		Size = UDim2.new( 1, -Reserve, 1, 0 );
		TextColor3 = Theme.textDim;
		Font = Theme.fontMedium;
		TextSize = Theme.textSize - 1;
		TextTruncate = Enum.TextTruncate.AtEnd;
	} );

	if ( Height == nil ) then
		Theme.__rows = Theme.__rows or { };
		table.insert( Theme.__rows, Row );
	end

	return Row, Label;
end

function Common.resizeRows( Theme: any )
	local Rows = Theme.__rows;

	if ( not Rows ) then
		return;
	end

	for Index = #Rows, 1, -1 do
		local Row = Rows[ Index ];

		if ( not Row.Parent ) then
			table.remove( Rows, Index );
			continue;
		end

		Row.Size = UDim2.new( 1, 0, 0, Theme.rowHeight );
	end
end

function Common.field( Parent: Instance, Theme: any, Text: string, ControlHeight: number? ): ( Frame, TextLabel, Frame )
	local Field = P.create( "Frame", {
		BackgroundTransparency = 1;
		Size = UDim2.new( 1, 0, 0, 0 );
		AutomaticSize = Enum.AutomaticSize.Y;
		Parent = Parent;
	} ) :: Frame;
	P.listLayout( Field, Theme.fieldGap or 6 );
	P.paddingXY( Field, 6, 2 );

	local Label = P.label( Field, Text, {
		Theme = Theme;
		Size = UDim2.new( 1, 0, 0, 16 );
		TextColor3 = Theme.textDim;
		Font = Theme.fontMedium;
		TextSize = Theme.textSize - 1;
		TextTruncate = Enum.TextTruncate.AtEnd;
	} );

	local Control = P.create( "Frame", {
		BackgroundTransparency = 1;
		Size = UDim2.new( 1, 0, 0, ControlHeight or Theme.controlHeight or Theme.rowHeight );
		Parent = Field;
	} ) :: Frame;

	return Field, Label, Control;
end

function Common.clickable( Parent: Instance, Theme: any, Options: any? ): TextButton
	Options = Options or { };

	local function BaseColor( ): Color3
		if ( typeof( Options.getBaseColor ) == "function" ) then
			return Options.getBaseColor( );
		end

		return Options.baseColor or Theme.surfaceAlt;
	end

	local function HoverColor( ): Color3
		if ( typeof( Options.getHoverColor ) == "function" ) then
			return Options.getHoverColor( );
		end

		return Options.hoverColor or Theme.controlHover or Theme.overlay;
	end

	local function HoverStrokeColor( ): Color3
		if ( typeof( Options.getHoverStrokeColor ) == "function" ) then
			return Options.getHoverStrokeColor( );
		end

		return Options.hoverStrokeColor or Theme.strokeBright;
	end

	local Button = P.create( "TextButton", {
		AutoButtonColor = false;
		BackgroundColor3 = BaseColor( );
		Text = "";
		ClipsDescendants = true;
		Parent = Parent;
	} ) :: TextButton;
	P.corner( Button, Theme.cornerSmall );
	local PressScale = P.create( "UIScale", { Scale = 1, Parent = Button } );
	local Stroke = nil;

	if ( Options.stroke ~= false ) then
		Stroke = P.stroke( Button, Theme.stroke, 1, 0 );
	end

	local Tracker = { maid = Options.maid };
	Common.connect( Tracker, Button.MouseEnter, function( )
		if ( Options.disabled == true ) then
			return;
		end

		P.tween( Button, Theme.fast or 0.1, { BackgroundColor3 = HoverColor( ) } );

		if ( Stroke ) then
			Stroke.Color = HoverStrokeColor( );
		end
	end );
	Common.connect( Tracker, Button.MouseLeave, function( )
		P.tween( Button, Theme.fast or 0.1, { BackgroundColor3 = BaseColor( ) } );
		P.tween( PressScale, Theme.fast or 0.1, { Scale = 1 } );

		if ( Stroke ) then
			Stroke.Color = Theme.stroke;
		end
	end );
	Common.connect( Tracker, Button.MouseButton1Down, function( )
		if ( Options.disabled ~= true ) then
			P.tween( PressScale, Theme.fast or 0.1, { Scale = 0.985 } );
		end
	end );
	Common.connect( Tracker, Button.MouseButton1Up, function( )
		P.tween( PressScale, Theme.fast or 0.1, { Scale = 1 } );
	end );

	return Button;
end

return Common;]];
		["ui/components/dropdown.lua"] = [[
local P = require("ui/primitives.lua")
local Icons = require("ui/icons.lua")
local Common = require("ui/components/common.lua")
local Maid = require("core/maid.lua")

local function optValue(o)
	return typeof(o) == "table" and o.value or o
end

local function optLabel(o)
	if typeof(o) == "table" then
		return tostring(o.label or o.value)
	end
	return tostring(o)
end

local OPTION_HEIGHT = 22
local OPTION_GAP = 2
local LIST_PADDING = 5
local MAX_VISIBLE = 7
local CONTROL_SHARE = 0.52
-- Long fixed lists and every dynamic list (players, catalogs, saved spots) get a search field.
local SEARCH_THRESHOLD = 12

return function(section: Instance, spec, ctx)
	local theme = ctx.theme
	local key = spec.key
	local multi = spec.multi == true or spec.multiple == true
	if ctx.config[key] == nil then
		if multi then
			ctx.config[key] = if typeof(spec.default) == "table" then table.clone(spec.default) else {}
		else
			ctx.config[key] = spec.default
		end
	end

	local root = P.create("Frame", {
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Parent = section,
	})
	P.listLayout(root, theme.fieldGap or 6)

	local headerHost, fieldLabel = Common.row(root, theme, spec.label or key, nil, 0)
	fieldLabel.Size = UDim2.new(1 - CONTROL_SHARE, -8, 1, 0)

	local header = Common.clickable(headerHost, theme, {
		maid = ctx.maid,
		baseColor = theme.control or theme.surface,
		hoverColor = theme.controlHover or theme.overlay,
		stroke = true,
	})
	header.AnchorPoint = Vector2.new(1, 0.5)
	header.Position = UDim2.new(1, 0, 0.5, 0)
	header.Size = UDim2.new(CONTROL_SHARE, 0, 0, theme.controlHeight or 26)
	P.paddingXY(header, 9, 0)

	local valueLabel = P.label(header, "", {
		Theme = theme,
		Size = UDim2.new(1, -28, 1, 0),
		TextColor3 = theme.text,
		Font = theme.fontMedium,
		TextSize = theme.textSizeSmall,
		TextTruncate = Enum.TextTruncate.AtEnd,
	})
	local chevron = Icons.mount(header, "tabler:chevron-down", {
		size = 13,
		color = theme.textFaint,
		anchorPoint = Vector2.new(1, 0.5),
		position = UDim2.new(1, -8, 0.5, 0),
	})

	local listHost = P.create("Frame", {
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		ClipsDescendants = true,
		Visible = false,
		Parent = root,
	})

	local listFrame = P.create("Frame", {
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, -6, 0, 0),
		Size = UDim2.new(CONTROL_SHARE, -6, 1, 0),
		BackgroundColor3 = theme.elevated,
		BorderSizePixel = 0,
		Parent = listHost,
	})
	P.corner(listFrame, theme.cornerSmall)

	local listStroke = P.stroke(listFrame, theme.stroke, 1, 0.15)

	local scroll = P.create("ScrollingFrame", {
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.fromScale(1, 1),
		CanvasSize = UDim2.new(),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollingDirection = Enum.ScrollingDirection.Y,
		ScrollBarThickness = 0,
		ScrollBarImageColor3 = theme.textFaint,
		ScrollBarImageTransparency = 0.4,
		Parent = listFrame,
	})
	P.padding(scroll, LIST_PADDING)
	P.listLayout(scroll, OPTION_GAP)

	local SearchBox;
	local EmptyLabel;
	local Searchable = spec.searchable == true or typeof( spec.getOptions ) == "function"
		or ( typeof( spec.options ) == "table" and #spec.options > SEARCH_THRESHOLD );
	local SearchHeight = Searchable and 34 or 0;
	if ( SearchHeight > 0 ) then
		listFrame.Size = UDim2.fromScale( 1, 1 );
		SearchBox = P.create( "TextBox", {
			Position = UDim2.fromOffset( LIST_PADDING, LIST_PADDING ),
			Size = UDim2.new( 1, -LIST_PADDING * 2, 0, 26 ),
			BackgroundColor3 = theme.control,
			BorderSizePixel = 0,
			Text = "",
			PlaceholderText = "Search items",
			ClearTextOnFocus = false,
			FontFace = theme.fontFace,
			TextSize = theme.textSizeSmall,
			TextColor3 = theme.text,
			PlaceholderColor3 = theme.textFaint,
			TextXAlignment = Enum.TextXAlignment.Left,
			Parent = listFrame,
		} );
		P.corner( SearchBox, theme.cornerSmall );
		P.paddingXY( SearchBox, 7, 0 );
		scroll.Position = UDim2.fromOffset( 0, SearchHeight );
		scroll.Size = UDim2.new( 1, 0, 1, -SearchHeight );
		EmptyLabel = P.label( scroll, "No matches", {
			Theme = theme,
			Size = UDim2.new( 1, 0, 0, OPTION_HEIGHT ),
			TextColor3 = theme.textFaint,
			TextSize = theme.textSizeSmall,
			Visible = false,
		} );
	end

	local options = {}
	local optionButtons = {}
	local initialized = false
	local renderedValue = nil
	local optionMaid = Maid.new()
	ctx.maid:give(function()
		optionMaid:destroy()
	end)

	local open = false

	local function openHeight(): number
		local count = 0;
		for _, Entry in optionButtons do
			if ( Entry.button.Visible ) then
				count += 1;
			end
		end
		if ( SearchBox ) then
			count = math.max( 1, count );
		end
		if count == 0 then
			return 0
		end
		local content = count * OPTION_HEIGHT + (count - 1) * OPTION_GAP + LIST_PADDING * 2
		local ceiling = MAX_VISIBLE * OPTION_HEIGHT + (MAX_VISIBLE - 1) * OPTION_GAP + LIST_PADDING * 2
		return SearchHeight + math.min(content, ceiling)
	end

	local function FilterOptions( )
		local Query = SearchBox and string.lower( SearchBox.Text ) or "";
		Query = string.gsub( string.gsub( Query, "^%s+", "" ), "%s+$", "" );
		local Matches = 0;
		for _, Entry in optionButtons do
			local Visible = string.find( string.lower( Entry.label.Text ), Query, 1, true ) ~= nil;
			Entry.button.Visible = Visible;
			if ( Visible ) then
				Matches += 1;
			end
		end
		if ( EmptyLabel ) then
			EmptyLabel.Visible = Matches == 0;
		end
		scroll.CanvasPosition = Vector2.zero;
		if ( open ) then
			listHost.Size = UDim2.new( 1, 0, 0, openHeight( ) );
		end
	end
	if ( SearchBox ) then
		Common.connect( ctx, SearchBox : GetPropertyChangedSignal( "Text" ), FilterOptions );
	end

	local function currentValues()
		if multi then
			local v = ctx.config[key]
			if typeof(v) ~= "table" then
				v = {}
				ctx.config[key] = v
			end
			return v
		end
		return ctx.config[key]
	end

	local function isSelected(value): boolean
		if multi then
			for _, v in currentValues() do
				if v == value then
					return true
				end
			end
			return false
		end
		return ctx.config[key] == value
	end

	local function summary(): string
		if multi then
			local labels = {}
			for _, o in options do
				if isSelected(optValue(o)) then
					table.insert(labels, optLabel(o))
				end
			end
			if #labels == 0 then
				return "None"
			end
			if #labels > 2 then
				return ("%d selected"):format(#labels)
			end
			return table.concat(labels, ", ")
		end
		for _, o in options do
			if optValue(o) == ctx.config[key] then
				return optLabel(o)
			end
		end
		return options[1] and optLabel(options[1]) or "-"
	end

	local control = {}

	local function refreshSelection()
		valueLabel.Text = summary()
		for _, entry in optionButtons do
			local on = isSelected(entry.value)

			entry.button.BackgroundColor3 = on and (theme.accentFaint or theme.accentDim) or theme.elevated
			if entry.stripe then
				entry.stripe.Visible = on
				entry.stripe.BackgroundColor3 = theme.accent
			end
			if entry.checkIcon then
				entry.checkIcon.Visible = on
				Icons.setColor(entry.checkIcon, on and theme.accentBright or theme.textFaint)
			end
			if entry.boxIcon then
				entry.boxIcon.Visible = not on
			end
			entry.label.TextColor3 = on and theme.text or theme.textDim
		end
	end

	local function choose(value)
		local nextValue
		if multi then

			local list = table.clone(currentValues())
			local idx = table.find(list, value)
			if idx then
				table.remove(list, idx)
			else
				table.insert(list, value)
			end
			nextValue = list
		else
			nextValue = value
		end
		control.set(nextValue)
		if not multi then control.setOpen(false) end
	end

	local function valuesEqual(a, b): boolean
		if not multi then
			return a == b
		end
		if typeof(a) ~= "table" or typeof(b) ~= "table" or #a ~= #b then
			return false
		end
		for index, value in a do
			if b[index] ~= value then
				return false
			end
		end
		return true
	end

	local function snapshot(value)
		return if multi and typeof(value) == "table" then table.clone(value) else value
	end

	local function normalizeValue(value)
		if #options == 0 then
			return if multi and typeof(value) ~= "table" then {} else value
		end
		local valid = {}
		for _, option in options do
			local optionValue = optValue(option)
			if optionValue ~= nil then
				valid[optionValue] = true
			end
		end
		if multi then
			local filtered = {}
			if typeof(value) == "table" then
				for _, selected in value do
					if valid[selected] and table.find(filtered, selected) == nil then
						table.insert(filtered, selected)
					end
				end
			end
			return filtered
		end
		return if valid[value] then value else optValue(options[1])
	end

	function control.getValue()
		local value = currentValues()
		return if multi then table.clone(value) else value
	end
	control.get = control.getValue

	function control.set(value, silent: boolean?)
		local previous = snapshot(if initialized then renderedValue else currentValues())
		value = normalizeValue(value)
		if multi then
			ctx.config[key] = if typeof(value) == "table" then table.clone(value) else {}
		else
			ctx.config[key] = value
		end
		refreshSelection()
		local changed = not valuesEqual(previous, ctx.config[key])
		renderedValue = snapshot(ctx.config[key])
		if changed and not silent then
			if spec.onChange then
				Common.safeCall(ctx, "select onChange " .. tostring(key), spec.onChange, ctx.config[key])
			end
			ctx.dispatch(key, ctx.config[key], "select")
		end
	end
	function control.setValue(value, dispatchChange: boolean?)
		control.set(value, dispatchChange == false)
	end

	local function rebuild()
		optionMaid:destroy()
		optionMaid = Maid.new()
		for _, entry in optionButtons do
			entry.button:Destroy()
		end
		table.clear(optionButtons)
		for _, o in options do
			local value = optValue(o)
			local b = Common.clickable(scroll, theme, {
				maid = optionMaid,
				getBaseColor = function()
					return isSelected(value) and (theme.accentFaint or theme.accentDim) or theme.elevated
				end,
				hoverColor = theme.controlHover or theme.overlay,
				stroke = false,
			})
			b.Size = UDim2.new(1, 0, 0, OPTION_HEIGHT)

			local stripe = P.create("Frame", {
				AnchorPoint = Vector2.new(0, 0.5),
				Position = UDim2.new(0, 3, 0.5, 0),
				Size = UDim2.new(0, 2, 1, -12),
				BackgroundColor3 = theme.accent,
				BorderSizePixel = 0,
				Visible = false,
				Parent = b,
			})
			P.corner(stripe, 1)

			local inner = P.create("Frame", {
				Size = UDim2.fromScale(1, 1),
				BackgroundTransparency = 1,
				Parent = b,
			})
			P.paddingXY(inner, 9, 0)
			local rowLayout = P.listLayout(inner, 8, Enum.FillDirection.Horizontal)
			rowLayout.VerticalAlignment = Enum.VerticalAlignment.Center

			local checkIcon: ImageLabel? = nil
			local boxIcon: ImageLabel? = nil

			if multi then
				local tickSlot = P.create("Frame", {
					Size = UDim2.fromOffset(14, 14),
					BackgroundTransparency = 1,
					Parent = inner,
				})
				boxIcon = Icons.mount(tickSlot, "tabler:square", {
					size = 12,
					color = theme.textFaint,
					anchorPoint = Vector2.new(0.5, 0.5),
					position = UDim2.fromScale(0.5, 0.5),
				})
				checkIcon = Icons.mount(tickSlot, "tabler:square-check", {
					size = 12,
					color = theme.accentBright,
					anchorPoint = Vector2.new(0.5, 0.5),
					position = UDim2.fromScale(0.5, 0.5),
				})
				if checkIcon then
					checkIcon.Visible = false
				end
			end

			local optionLabel = P.label(inner, optLabel(o), {
				Theme = theme,
				Size = UDim2.new(1, if multi then -22 else 0, 0, 16),
				TextSize = theme.textSizeSmall,
				TextYAlignment = Enum.TextYAlignment.Center,
				TextColor3 = theme.textDim,
			})

			Common.connect({ maid = optionMaid }, b.MouseButton1Click, function()
				choose(value)
			end)
			table.insert(optionButtons, {
				button = b,
				value = value,
				label = optionLabel,
				stripe = stripe,
				checkIcon = checkIcon,
				boxIcon = boxIcon,
			})
		end
		refreshSelection()
		FilterOptions( );
		if open then

			listHost.Size = UDim2.new(1, 0, 0, openHeight())
		end
	end

	function control.refresh()
		local previous = snapshot(if initialized then renderedValue else currentValues())
		options = {}
		local source = spec.options or {}
		if typeof(spec.getOptions) == "function" then
			local ok, resolved = pcall(spec.getOptions)
			if ok and typeof(resolved) == "table" then
				source = resolved
			elseif not ok then
				Common.warn(ctx, "select getOptions", key, "->", resolved)
			end
		end
		for _, o in source do
			table.insert(options, o)
		end
		ctx.config[key] = normalizeValue(currentValues())
		rebuild()
		local changed = not valuesEqual(previous, ctx.config[key])
		renderedValue = snapshot(ctx.config[key])
		if initialized and changed then
			if spec.onChange then
				Common.safeCall(ctx, "select onChange " .. tostring(key), spec.onChange, ctx.config[key])
			end
			ctx.dispatch(key, ctx.config[key], "select")
		end
		initialized = true
	end

	local function paintHeaderStroke()
		local stroke = header:FindFirstChildOfClass("UIStroke")
		if not stroke then
			return
		end
		if open then
			stroke.Color = theme.accent
			stroke.Transparency = 0.3
		else
			stroke.Color = theme.stroke
			stroke.Transparency = 0.35
		end
	end

	function control.setOpen(value: boolean)

		if value and #optionButtons == 0 and not SearchBox then
			value = false
		end
		open = value
		if ( SearchBox and not value ) then
			SearchBox : ReleaseFocus( );
			SearchBox.Text = "";
		end

		local time = theme.fast or 0.07
		if value then
			listHost.Visible = true
		end
		local tween = P.tween(listHost, time, {
			Size = UDim2.new(1, 0, 0, if value then openHeight() else 0),
		})
		if not value then

			if tween then
				tween.Completed:Once(function()
					if not open then
						listHost.Visible = false
					end
				end)
			else
				listHost.Visible = false
			end
		end

		if chevron then
			-- Swap the glyph instead of rotating it: Roblox does not draw rotation inside a clipping
			-- ancestor, and every menu control sits in a scrolling page.
			Icons.apply(chevron, Icons.getAsset(if value then "tabler:chevron-up" else "tabler:chevron-down"))
			Icons.setColor(chevron, if value then theme.accentBright else theme.textFaint)
		end
		paintHeaderStroke()
	end

	Common.connect(ctx, header.MouseButton1Click, function()
		if not open and typeof(spec.getOptions) == "function" then
			control.refresh()
		end
		control.setOpen(not open)
	end)

	Common.connect(ctx, header.MouseLeave, function()
		if open then
			paintHeaderStroke()
		end
	end)

	control.refresh()
	Common.onTheme(ctx, function()
		if ( SearchBox ) then
			SearchBox.BackgroundColor3 = theme.control;
			SearchBox.TextColor3 = theme.text;
			SearchBox.PlaceholderColor3 = theme.textFaint;
			EmptyLabel.TextColor3 = theme.textFaint;
		end
		fieldLabel.TextColor3 = theme.textDim
		header.BackgroundColor3 = theme.control or theme.surface
		valueLabel.TextColor3 = theme.text
		listFrame.BackgroundColor3 = theme.elevated
		listStroke.Color = theme.stroke
		scroll.ScrollBarImageColor3 = theme.textFaint
		paintHeaderStroke()
		Icons.setColor(chevron, open and theme.accentBright or theme.textFaint)
		refreshSelection()
	end)

	return control
end]];
		["ui/components/group.lua"] = [[
local P = require("ui/primitives.lua")
local Icons = require("ui/icons.lua")
local Common = require("ui/components/common.lua")
local Toggle = require("ui/components/toggle.lua")

-- A row that opens a set of sub-options. With a toggle it reads like any other toggle row (checkbox on
-- the left, label beside it); on the right it shows how many options it holds and a chevron that turns
-- down while open.
local TOGGLE_SLOT = 24 -- puts the 12 px checkbox at x = 6, where plain toggle rows draw theirs
local LABEL_X = 26 -- plain toggle labels start here
local COUNT_WIDTH = 44

local function CountItems(items): number
	local count = 0
	for _, item in items or {} do
		if typeof(item) == "table" and item.type ~= "hint" and item.type ~= "separator" and item.type ~= "spacer" then
			count += 1
		end
	end
	return count
end

return function(section: Instance, spec, ctx)
	local theme = ctx.theme
	local toggleKey = spec.toggleKey or spec.key
	local expanded = spec.defaultExpanded == true

	local root = P.create("Frame", {
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Parent = section,
	})
	P.listLayout(root, theme.fieldGap or 6)

	local header = P.create("Frame", {
		Size = UDim2.new(1, 0, 0, theme.rowHeight),
		BackgroundColor3 = theme.control or theme.surface,
		BackgroundTransparency = 1,
		Parent = root,
	})
	P.corner(header, theme.cornerSmall)

	local toggleReserve = toggleKey and TOGGLE_SLOT or 0
	local expandBtn = P.create("TextButton", {
		Position = UDim2.fromOffset(toggleReserve, 0),
		Size = UDim2.new(1, -toggleReserve, 1, 0),
		BackgroundTransparency = 1,
		AutoButtonColor = false,
		Text = "",
		Parent = header,
	}) :: TextButton

	local titleX = toggleKey and (LABEL_X - TOGGLE_SLOT) or 6
	local titleLabel = P.label(expandBtn, spec.label or toggleKey or "Options", {
		Theme = theme,
		Position = UDim2.fromOffset(titleX, 0),
		Size = UDim2.new(1, -(titleX + COUNT_WIDTH + 6), 1, 0),
		TextColor3 = theme.text,
		Font = theme.fontMedium,
		TextSize = theme.textSize - 1,
		TextTruncate = Enum.TextTruncate.AtEnd,
	})

	local meta = P.create("Frame", {
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -6, 0.5, 0),
		Size = UDim2.fromOffset(COUNT_WIDTH, 14),
		BackgroundTransparency = 1,
		Parent = expandBtn,
	})
	local metaLayout = P.listLayout(meta, 6, Enum.FillDirection.Horizontal)
	metaLayout.HorizontalAlignment = Enum.HorizontalAlignment.Right
	metaLayout.VerticalAlignment = Enum.VerticalAlignment.Center

	local itemCount = CountItems(spec.items)
	local countLabel = P.label(meta, tostring(itemCount), {
		Theme = theme,
		AutomaticSize = Enum.AutomaticSize.X,
		Size = UDim2.fromOffset(0, 14),
		TextSize = theme.textSizeSmall,
		TextXAlignment = Enum.TextXAlignment.Right,
		LayoutOrder = 1,
		Visible = itemCount > 0,
	})
	local chevron = Icons.mount(meta, "tabler:chevron-right", {
		size = 12,
		color = theme.textFaint,
	})
	if chevron then
		chevron.LayoutOrder = 2
	end

	local RefreshHeader;

	if toggleKey then
		local toggleSlot = P.create("Frame", {
			Size = UDim2.new(0, TOGGLE_SLOT, 1, 0),
			BackgroundTransparency = 1,
			Parent = header,
		})
		local toggleSpec = table.clone(spec.toggleSpec or {})
		toggleSpec.type = "toggle"
		toggleSpec.key = toggleKey
		toggleSpec.label = toggleSpec.label or spec.label or toggleKey
		toggleSpec.hud = if toggleSpec.hud ~= nil then toggleSpec.hud else spec.hud
		toggleSpec.inline = true
		local control = Toggle(toggleSlot, toggleSpec, ctx)
		-- Every path that flips the switch (click, sync, mirrors) goes through set, so the title
		-- dims and brightens with it like a plain toggle's label.
		if control then
			local Set = control.set
			control.set = function( Value: boolean, Silent: boolean? )
				Set( Value, Silent );
				if ( RefreshHeader ) then RefreshHeader( ); end
			end
			control.setValue = control.set
		end
		if control and typeof(ctx.registerControl) == "function" then
			ctx.registerControl(toggleKey, control)
		elseif control and ctx.controls then
			ctx.controls[toggleKey] = control
		end
	end

	-- Sub-options sit indented behind a guide line, so it is obvious which toggle they belong to. The
	-- line lives beside the list, not in it: as a list item it took a whole row slot at the full height.
	local holder = P.create("Frame", {
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Visible = expanded,
		Parent = root,
	})
	local Guide = P.create("Frame", {
		Position = UDim2.fromOffset(6, 2),
		Size = UDim2.new(0, 1, 1, -4),
		BorderSizePixel = 0,
		BackgroundColor3 = theme.stroke,
		Parent = holder,
	})
	local body = P.create("Frame", {
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Parent = holder,
	})
	local BodyPadding = P.paddingXY(body, 0, 2)
	BodyPadding.PaddingLeft = UDim.new(0, 12)
	P.listLayout(body, theme.controlGap or 6)

	local Hovered = false;
	RefreshHeader = function( )
		header.BackgroundColor3 = Hovered and ( theme.controlHover or theme.overlay ) or theme.overlay;
		P.tween( header, theme.fast, { BackgroundTransparency = Hovered and 0.55 or 1 } );
		Icons.setColor( chevron, ( expanded or Hovered ) and theme.accentBright or theme.textFaint );
		countLabel.TextColor3 = expanded and theme.textDim or theme.textFaint;
		titleLabel.TextColor3 = ( toggleKey and ctx.config[ toggleKey ] ~= true ) and theme.textDim or theme.text;
		Guide.BackgroundColor3 = theme.stroke;
	end
	Common.connect( ctx, expandBtn.MouseEnter, function( )
		Hovered = true;
		RefreshHeader( );
	end )
	Common.connect( ctx, expandBtn.MouseLeave, function( )
		Hovered = false;
		RefreshHeader( );
	end )

	local function setExpanded(on: boolean, animated: boolean?)
		expanded = on
		holder.Visible = on
		-- A glyph swap, not a rotation: rotation does not render inside the scrolling page.
		if chevron then
			Icons.apply( chevron, Icons.getAsset( on and "tabler:chevron-down" or "tabler:chevron-right" ) );
		end
		RefreshHeader( );
	end

	Common.connect(ctx, expandBtn.MouseButton1Click, function()
		setExpanded(not expanded, true)
	end)

	if typeof(ctx.buildItems) == "function" then
		ctx.buildItems(body, spec.items or {}, ctx)
	end

	Common.onTheme(ctx, function()
		RefreshHeader( );
	end)

	setExpanded(expanded, false)
	return {
		setExpanded = function(on: boolean)
			setExpanded(on == true, false)
		end,
		isExpanded = function(): boolean
			return expanded
		end,
	}
end]];
		["ui/components/keybind.lua"] = [[
local Services = require("core/services.lua")
local Input = require("core/input.lua")
local P = require("ui/primitives.lua")
local Common = require("ui/components/common.lua")

local UserInputService = Services.UserInputService

return function(section: Instance, spec, ctx)
	local theme = ctx.theme
	local key = spec.key

	local MOUSE_BUTTON_LABELS = {}
	local MOUSE_KEYCODE_LABELS = {}
	local SIDE_MOUSE_KEYCODES = {}

	for _, inputType in Enum.UserInputType:GetEnumItems() do
		local number = string.match(inputType.Name, "^MouseButton(%d+)$")
		if number then
			MOUSE_BUTTON_LABELS[inputType] = "Mouse" .. number
		end
	end

	local knownMouseKeyLabels = {
		MouseLeftButton = "Mouse1",
		MouseRightButton = "Mouse2",
		MouseMiddleButton = "Mouse3",
		MouseBackButton = "Mouse4",
		MouseForwardButton = "Mouse5",
		MouseXButton1 = "Mouse4",
		MouseXButton2 = "Mouse5",
	}
	for _, keyCode in Enum.KeyCode:GetEnumItems() do
		local label = knownMouseKeyLabels[keyCode.Name]
		if label then
			MOUSE_KEYCODE_LABELS[keyCode] = label
			if label == "Mouse4" or label == "Mouse5" then
				SIDE_MOUSE_KEYCODES[keyCode] = true
			end
		end
	end

	local function validBinding(value): boolean
		if typeof(value) ~= "EnumItem" then
			return false
		end
		if ( spec.isValidBinding and not spec.isValidBinding( value ) ) then
			return false;
		end
		if value.EnumType == Enum.KeyCode then
			return true
		end
		return value.EnumType == Enum.UserInputType and MOUSE_BUTTON_LABELS[value] ~= nil
	end

	local defaultBinding = if validBinding(spec.default) then spec.default else Enum.KeyCode.Unknown
	local bound = if validBinding(ctx.config[key]) then ctx.config[key] else defaultBinding
	ctx.config[key] = bound

	local row = Common.row(section, theme, spec.label or key, nil, 66)

	local btn = Common.clickable(row, theme, {
		maid = ctx.maid,
		baseColor = theme.control or theme.surface,
		hoverColor = theme.controlHover or theme.overlay,
	})
	btn.AnchorPoint = Vector2.new(1, 0.5)
	btn.Position = UDim2.new(1, 0, 0.5, 0)
	btn.Size = UDim2.fromOffset(64, theme.controlHeight or 21)
	local btnLabel = P.label(btn, "", {
		Theme = theme,
		TextXAlignment = Enum.TextXAlignment.Center,
		TextSize = theme.textSizeSmall,
		TextColor3 = theme.accentBright,
		Font = theme.fontMedium,
		TextTruncate = Enum.TextTruncate.AtEnd,
	})

	local liveHandle = nil
	local listenConn = nil
	local control = {}

	local function displayName(value): string
		if value == Enum.KeyCode.Unknown then
			return spec.noneLabel or "None"
		end
		return MOUSE_BUTTON_LABELS[value] or MOUSE_KEYCODE_LABELS[value] or value.Name
	end

	local function render()
		btnLabel.Text = displayName(bound)
	end

	local function rebindLive()
		if liveHandle then
			liveHandle.disconnect()
			liveHandle = nil
		end
		if spec.mode and bound ~= Enum.KeyCode.Unknown then
			liveHandle = ctx.maid:give(Input.bind("ui." .. key, bound, spec.mode, function(state)
				if spec.onChange then
					Common.safeCall(ctx, "keybind callback " .. tostring(key), spec.onChange, state)
				end
			end))
		end
	end

	function control.set(k: EnumItem, silent: boolean?)
		-- Keep the previous assignment when a control rejects a captured key.
		if ( spec.isValidBinding and not spec.isValidBinding( k ) ) then
			ctx.config[ key ] = bound;
			render( );
			return;
		end
		local nextBinding = if validBinding(k) then k else defaultBinding
		local changed = nextBinding ~= bound
		bound = nextBinding
		ctx.config[key] = bound
		render()
		rebindLive()
		if changed and not silent then
			ctx.dispatch(key, bound, "keybind")
		end
	end
	function control.get(): EnumItem
		return bound
	end
	control.setValue = control.set
	control.getValue = control.get

	local function captureBinding(input: InputObject): (EnumItem?, boolean)
		if input.UserInputType == Enum.UserInputType.Keyboard then
			if input.KeyCode == Enum.KeyCode.Unknown then
				return nil, false
			elseif input.KeyCode == Enum.KeyCode.Escape then
				return nil, true
			elseif input.KeyCode == Enum.KeyCode.Backspace or input.KeyCode == Enum.KeyCode.Delete then
				return Enum.KeyCode.Unknown, true
			end
			return input.KeyCode, true
		elseif SIDE_MOUSE_KEYCODES[input.KeyCode] == true then
			return input.KeyCode, true
		elseif MOUSE_BUTTON_LABELS[input.UserInputType] ~= nil then
			return input.UserInputType, true
		elseif input.KeyCode ~= Enum.KeyCode.Unknown and MOUSE_KEYCODE_LABELS[input.KeyCode] ~= nil then
			return input.KeyCode, true
		end
		return nil, false
	end

	local listening = false
	Common.connect(ctx, btn.MouseButton1Click, function()
		if listening then
			return
		end
		listening = true
		btnLabel.Text = "..."
		if listenConn then
			listenConn:Disconnect()
		end
		listenConn = UserInputService.InputBegan:Connect(function(input)
			local captured, done = captureBinding(input)
			if not done then
				return
			end
			listenConn:Disconnect()
			listenConn = nil
			listening = false
			if captured then
				control.set(captured)
			else
				render()
			end
		end)
	end)
	ctx.maid:give(function()
		if listenConn then
			listenConn:Disconnect()
			listenConn = nil
		end
	end)

	render()
	rebindLive()
	Common.onTheme(ctx, function()
		btn.BackgroundColor3 = theme.control or theme.surface
		btnLabel.TextColor3 = theme.accentBright
	end)
	return control
end]];
		["ui/components/label.lua"] = [[
-- Text items: separators, spacers, badges, plain labels, and readouts. A readout is any label a game
-- updates live (it has an `id`) or a hint with `presentation = "status"`. It renders as a stat row: a
-- status dot (accent while it reports something, faint when it is empty or off), the name on the left and
-- the value on the right when the text is "Name  Value" (two or more spaces) or "Name: Value", and "|"-separated parts as
-- "name value · name value". Hint text otherwise never renders (CLAUDE.md rule 3).

-- Dependencies
local P = require( "ui/primitives.lua" );
local Runtime = require( "core/runtime.lua" );
local Common = require( "ui/components/common.lua" );

-- Cache
local StringGsub = string.gsub;
local StringMatch = string.match;
local StringFind = string.find;
local StringLower = string.lower;
local StringSplit = string.split;
local TableConcat = table.concat;

-- Constants
local READOUT_HEIGHT = 22;
local DOT_SIZE = 5;
-- Readouts that start with or contain one of these report nothing live, so their dot goes faint.
local IDLE_PATTERNS = { "^off", "^idle", "^none", "^empty", "^stopped", "^disabled", "^waiting", "not ", " off%.?$" };

-- Utilities
local function DeferSetText( Label: TextLabel, Text: string )
	Runtime.deferClient( function( )
		if ( Label.Parent ) then
			Label.Text = Text;
		end
	end );
end

local function Holder( Section: Instance, Height: number?, Automatic: boolean? ): Frame
	return P.create( "Frame", {
		BackgroundTransparency = 1;
		Size = UDim2.new( 1, 0, 0, Height or 0 );
		AutomaticSize = Automatic and Enum.AutomaticSize.Y or Enum.AutomaticSize.None;
		Parent = Section;
	} ) :: Frame;
end

local function Escape( Text: string ): string
	local Safe = StringGsub( Text, "&", "&amp;" );
	Safe = StringGsub( Safe, "<", "&lt;" );
	Safe = StringGsub( Safe, ">", "&gt;" );
	return Safe;
end

local function Trim( Text: string ): string
	return ( StringMatch( Text, "^%s*(.-)%s*$" ) );
end

local function IsPlaceholder( Text: string ): boolean
	return Text == "" or Text == "-" or Text == "--";
end

local function IsIdle( Text: string ): boolean
	if ( IsPlaceholder( Text ) ) then
		return true;
	end

	local Lower = StringLower( Text );

	for _, Pattern in IDLE_PATTERNS do
		if ( StringFind( Lower, Pattern ) ) then
			return true;
		end
	end

	return false;
end

-- "Rounds 3 | Trees 41" -> "<dim>Rounds</dim> 3 · <dim>Trees</dim> 41", as rich text in the theme's colours.
local function RichValue( Text: string, Theme: any ): string
	if ( IsPlaceholder( Text ) ) then
		return `<font color="#{ Theme.textFaint : ToHex( ) }">—</font>`;
	end

	local Dim = Theme.textDim : ToHex( );
	local Parts = { };

	for _, Part in StringSplit( Text, "|" ) do
		local Segment = Trim( Part );

		if ( Segment ~= "" ) then
			local Name, Value = StringMatch( Segment, "^(%a[%a%s]-)%s+([%-%+%$%d%.].*)$" );

			if ( Name ) then
				Parts[ #Parts + 1 ] = `<font color="#{ Dim }">{ Escape( Name ) }</font> { Escape( Value ) }`;
			end

			if ( not Name ) then
				Parts[ #Parts + 1 ] = Escape( Segment );
			end
		end
	end

	return TableConcat( Parts, `  <font color="#{ Theme.textFaint : ToHex( ) }">·</font>  ` );
end

-- Main
return function( Section: Instance, Spec: any, Context: any ): any
	local Theme = Context.theme;
	local Kind = Spec.type;

	if ( Kind == "separator" ) then
		local Line = P.create( "Frame", {
			AnchorPoint = Vector2.new( 0, 0.5 );
			Position = UDim2.new( 0, 6, 0.5, 0 );
			Size = UDim2.new( 1, -12, 0, 1 );
			BorderSizePixel = 0;
			Parent = Holder( Section, 12 );
		} );
		local function Paint( ) Line.BackgroundColor3 = Theme.strokeFaint; end
		Paint( );
		Common.onTheme( Context, Paint );
		return { };
	end

	if ( Kind == "spacer" ) then
		Holder( Section, tonumber( Spec.height ) or 8 );
		return { };
	end

	if ( Kind == "hint" and Spec.presentation ~= "status" ) then
		return { setText = function( ) end, setHint = function( ) end };
	end

	local Text = tostring( Spec.text or Spec.label or "" );

	if ( Kind == "badge" ) then
		local Pill = P.create( "Frame", {
			AutomaticSize = Enum.AutomaticSize.XY;
			BorderSizePixel = 0;
			Parent = Holder( Section, nil, true );
		} );
		P.corner( Pill, Theme.cornerSmall );
		P.paddingXY( Pill, 9, 4 );
		local Label = P.label( Pill, Text, {
			Theme = Theme;
			AutomaticSize = Enum.AutomaticSize.XY;
			Size = UDim2.fromOffset( 0, 14 );
			Font = Theme.fontMedium;
			TextSize = Theme.textSizeSmall;
		} );
		local function Paint( )
			Pill.BackgroundColor3 = Spec.color or Theme.accentFaint;
			Label.TextColor3 = Spec.textColor or Theme.accentBright;
		end
		Paint( );
		Common.onTheme( Context, Paint );
		return { setText = function( Value: string ) DeferSetText( Label, tostring( Value ) ); end };
	end

	local Readout = Spec.id ~= nil or Kind == "hint";

	if ( not Readout ) then
		local Wrapper = Holder( Section, nil, true );
		P.paddingXY( Wrapper, 6, 2 );
		local Label = P.label( Wrapper, Text, {
			Theme = Theme;
			Size = UDim2.new( 1, 0, 0, 0 );
			AutomaticSize = Enum.AutomaticSize.Y;
			TextWrapped = true;
			TextSize = Theme.textSize - 1;
			TextYAlignment = Enum.TextYAlignment.Top;
		} );
		local function Paint( ) Label.TextColor3 = Theme.textDim; end
		Paint( );
		Common.onTheme( Context, Paint );
		return { setText = function( Value: string ) DeferSetText( Label, tostring( Value ) ); end };
	end

	-- Inset like the rows and buttons around it.
	local RowHolder = Holder( Section, nil, true );
	P.paddingXY( RowHolder, 6, 0 );
	local Row = P.create( "Frame", {
		Size = UDim2.new( 1, 0, 0, READOUT_HEIGHT );
		AutomaticSize = Enum.AutomaticSize.Y;
		BorderSizePixel = 0;
		Parent = RowHolder;
	} );
	P.corner( Row, Theme.cornerSmall );
	local Padding = P.paddingXY( Row, 8, 4 );
	Padding.PaddingLeft = UDim.new( 0, 8 );
	local Layout = P.listLayout( Row, 8, Enum.FillDirection.Horizontal );
	Layout.VerticalAlignment = Enum.VerticalAlignment.Center;

	local Dot = P.create( "Frame", {
		Size = UDim2.fromOffset( DOT_SIZE, DOT_SIZE );
		BorderSizePixel = 0;
		LayoutOrder = 1;
		Parent = Row;
	} );
	P.corner( Dot, DOT_SIZE );

	local NameLabel = P.label( Row, "", {
		Theme = Theme;
		AutomaticSize = Enum.AutomaticSize.X;
		Size = UDim2.fromOffset( 0, READOUT_HEIGHT - 8 );
		TextSize = Theme.textSizeSmall;
		LayoutOrder = 2;
	} );

	local ValueLabel = P.label( Row, "", {
		Theme = Theme;
		Size = UDim2.new( 0, 0, 0, READOUT_HEIGHT - 8 );
		AutomaticSize = Enum.AutomaticSize.Y;
		Font = Theme.fontMedium;
		TextSize = Theme.textSizeSmall;
		TextWrapped = true;
		RichText = true;
		LayoutOrder = 3;
	} );
	-- The value takes whatever width the name leaves.
	P.create( "UIFlexItem", { FlexMode = Enum.UIFlexMode.Fill, Parent = ValueLabel } );

	local Current = Text;

	local function Render( )
		local Value = Trim( Current );
		local Name, Rest = StringMatch( Value, "^(%S[^|\n]-)%s%s+(%S.*)$" );
		local Multiline = StringFind( Value, "\n" ) ~= nil;

		-- "Active: Rage" reads the same as "Active  Rage".
		if ( not Name ) then
			Name, Rest = StringMatch( Value, "^(%a[^:|\n]-):%s+(%S.*)$" );
		end

		-- "Wins 0  |  Losses 0" is a list of parts, not a name and a value.
		if ( Multiline or ( Rest and StringFind( Rest, "^|" ) ) ) then
			Name = nil;
			Rest = nil;
		end

		NameLabel.Visible = Name ~= nil;
		NameLabel.Text = Name or "";
		ValueLabel.TextXAlignment = Name and Enum.TextXAlignment.Right or Enum.TextXAlignment.Left;
		ValueLabel.Text = if ( Multiline ) then Escape( Value ) else RichValue( Rest or Value, Theme );

		Row.BackgroundColor3 = Theme.surfaceAlt;
		NameLabel.TextColor3 = Theme.textDim;
		ValueLabel.TextColor3 = Theme.text;
		Dot.BackgroundColor3 = IsIdle( Rest or Value ) and Theme.textFaint or Theme.accent;
	end

	Render( );
	Common.onTheme( Context, Render );
	return {
		setText = function( Value: string )
			Runtime.deferClient( function( )
				if ( not Row.Parent ) then
					return;
				end

				Current = tostring( Value );
				Render( );
			end );
		end;
		setHint = function( ) end;
	};
end]];
		["ui/components/profiles.lua"] = [[
-- Profiles: one set of controls per profile (Kontra's per-weapon-class aim tuning), switched by a tab
-- strip at the top of the block so it is always visible which profile is being edited.

-- Dependencies
local P = require( "ui/primitives.lua" );
local Common = require( "ui/components/common.lua" );

-- Main
return function( Section: Instance, Spec: any, Context: any ): any
	local Theme = Context.theme;
	local Names = { };
	local Panels = { };
	local Tabs = { };

	for _, Profile in Spec.profiles or { } do
		local Name = Profile.label;

		if ( typeof( Name ) == "string" and Name ~= "" and not table.find( Names, Name ) ) then
			Names[ #Names + 1 ] = Name;
		end
	end

	if ( #Names == 0 ) then
		return nil;
	end

	local Root = P.create( "Frame", {
		BackgroundTransparency = 1;
		Size = UDim2.new( 1, 0, 0, 0 );
		AutomaticSize = Enum.AutomaticSize.Y;
		Parent = Section;
	} );
	P.listLayout( Root, Theme.fieldGap or 6 );

	if ( Spec.label ) then
		local Caption = P.label( Root, Spec.label, {
			Theme = Theme;
			Size = UDim2.new( 1, 0, 0, 18 );
			Font = Theme.fontMedium;
			TextSize = Theme.textSizeSmall;
		} );
		P.paddingXY( Caption, 6, 0 );
		Common.onTheme( Context, function( ) Caption.TextColor3 = Theme.textFaint; end );
		Caption.TextColor3 = Theme.textFaint;
	end

	local Strip = P.create( "ScrollingFrame", {
		Size = UDim2.new( 1, 0, 0, 30 );
		BorderSizePixel = 0;
		ScrollBarThickness = 0;
		ScrollingDirection = Enum.ScrollingDirection.X;
		CanvasSize = UDim2.new( );
		AutomaticCanvasSize = Enum.AutomaticSize.X;
		Parent = Root;
	} );
	P.corner( Strip, Theme.cornerSmall );
	P.padding( Strip, 2 );
	P.listLayout( Strip, 2, Enum.FillDirection.Horizontal );

	local Active: string? = nil;

	local function Paint( )
		Strip.BackgroundColor3 = Theme.control;

		for Name, Tab in Tabs do
			local On = Name == Active;
			Tab.BackgroundColor3 = On and Theme.accent or Theme.control;
			Tab.BackgroundTransparency = On and 0 or 1;
			Tab.TextColor3 = On and Theme.background or Theme.textDim;
			Tab.FontFace = On and Theme.fontFaceBold or Theme.fontFaceMedium;
		end
	end

	-- The selection is navigation, never a saved game setting. Child controls keep their own keys
	-- and stay registered while their panel is hidden.
	local function Show( Name: string ): boolean
		if ( not Panels[ Name ] ) then
			return false;
		end

		Active = Name;

		for Label, Panel in Panels do
			Panel.Visible = Label == Name;
		end

		Paint( );
		return true;
	end

	for Order, Name in Names do
		local Tab = P.create( "TextButton", {
			Size = UDim2.new( 0, 0, 1, 0 );
			AutomaticSize = Enum.AutomaticSize.X;
			BorderSizePixel = 0;
			AutoButtonColor = false;
			Text = Name;
			TextSize = Theme.textSizeSmall;
			LayoutOrder = Order;
			Parent = Strip;
		} );
		P.corner( Tab, Theme.cornerSmall );
		P.paddingXY( Tab, 12, 0 );
		Tabs[ Name ] = Tab;
		Common.connect( Context, Tab.Activated, function( ) Show( Name ); end );
	end

	for _, Profile in Spec.profiles do
		local Name = Profile.label;

		if ( not table.find( Names, Name ) or Panels[ Name ] ) then
			continue;
		end

		local Panel = P.create( "Frame", {
			Name = "Profile_" .. Name;
			BackgroundTransparency = 1;
			Size = UDim2.new( 1, 0, 0, 0 );
			AutomaticSize = Enum.AutomaticSize.Y;
			Visible = false;
			Parent = Root;
		} );
		P.listLayout( Panel, Theme.controlGap or 4 );
		Panels[ Name ] = Panel;
		Context.buildItems( Panel, Profile.items or { } );
	end

	Show( table.find( Names, Spec.defaultProfile ) and Spec.defaultProfile or Names[ 1 ] );
	Common.onTheme( Context, Paint );

	return {
		selectProfile = Show;
		getProfile = function( ): string?
			return Active;
		end;
	};
end]];
		["ui/components/segmented.lua"] = [[
-- Segmented control: a select with two or three short fixed options, shown as one row of buttons
-- so the choice is visible without opening anything. ui/init.lua routes qualifying selects here;
-- the control keeps the select contract (set/get/setValue/getValue, dispatch type "select").

-- Dependencies
local P = require( "ui/primitives.lua" );
local Common = require( "ui/components/common.lua" );

-- Utilities
local function OptionValue( Option: any ): any
	if ( typeof( Option ) == "table" ) then
		return Option.value;
	end

	return Option;
end

local function OptionLabel( Option: any ): string
	if ( typeof( Option ) == "table" ) then
		return tostring( Option.label or Option.value );
	end

	return tostring( Option );
end

-- Main
return function( Section: Instance, Spec: any, Context: any ): any
	local Theme = Context.theme;
	local Key = Spec.key;
	local Options = Spec.options or { };

	local function Valid( Value: any ): boolean
		for _, Option in Options do
			if ( OptionValue( Option ) == Value ) then
				return true;
			end
		end

		return false;
	end

	local Value = Context.config[ Key ];

	if ( not Valid( Value ) ) then
		Value = Valid( Spec.default ) and Spec.default or OptionValue( Options[ 1 ] );
	end

	Context.config[ Key ] = Value;

	local Row, Label = Common.row( Section, Theme, Spec.label or Key, nil, 168 );
	local Track = P.create( "Frame", {
		AnchorPoint = Vector2.new( 1, 0.5 );
		Position = UDim2.new( 1, 0, 0.5, 0 );
		Size = UDim2.new( 0.56, 0, 0, Theme.controlHeight or 26 );
		BorderSizePixel = 0;
		Parent = Row;
	} );
	Label.Size = UDim2.new( 0.44, -8, 1, 0 );
	P.corner( Track, Theme.cornerSmall );
	local TrackStroke = P.stroke( Track, Theme.stroke, 1, 0 );
	P.padding( Track, 2 );
	P.listLayout( Track, 2, Enum.FillDirection.Horizontal );

	local Buttons = { };
	local Control = { };

	local function Render( )
		Track.BackgroundColor3 = Theme.control;
		TrackStroke.Color = Theme.stroke;
		Label.TextColor3 = Theme.textDim;

		for _, Entry in Buttons do
			local On = Entry.value == Value;
			Entry.button.BackgroundColor3 = Theme.overlay;
			Entry.button.BackgroundTransparency = On and 0 or 1;
			Entry.button.TextColor3 = On and Theme.accent or Theme.textDim;
			Entry.button.FontFace = Theme.fontFaceMedium;
		end
	end

	for Order, Option in Options do
		local Button = P.create( "TextButton", {
			Size = UDim2.new( 1 / #Options, -2 * ( #Options - 1 ) / #Options, 1, 0 );
			BorderSizePixel = 0;
			AutoButtonColor = false;
			Text = OptionLabel( Option );
			TextSize = Theme.textSizeSmall;
			TextTruncate = Enum.TextTruncate.AtEnd;
			LayoutOrder = Order;
			Parent = Track;
		} );
		P.corner( Button, Theme.cornerSmall );
		Buttons[ #Buttons + 1 ] = { button = Button, value = OptionValue( Option ) };
		Common.connect( Context, Button.Activated, function( )
			Control.set( OptionValue( Option ) );
		end );
	end

	function Control.set( Next: any, Silent: boolean? )
		if ( not Valid( Next ) ) then
			return;
		end

		local Changed = Next ~= Value;
		Value = Next;
		Context.config[ Key ] = Value;
		Render( );

		if ( not Changed or Silent ) then
			return;
		end

		if ( Spec.onChange ) then
			Common.safeCall( Context, "select onChange " .. tostring( Key ), Spec.onChange, Value );
		end

		Context.dispatch( Key, Value, "select" );
	end

	function Control.get( ): any
		return Value;
	end

	function Control.refresh( ) end

	Control.setValue = Control.set;
	Control.getValue = Control.get;

	Render( );
	Common.onTheme( Context, Render );
	return Control;
end]];
		["ui/components/slider.lua"] = [[
local Services = require("core/services.lua")
local Util = require("core/util.lua")
local P = require("ui/primitives.lua")
local Common = require("ui/components/common.lua")

local UserInputService = Services.UserInputService
local TRACK_HEIGHT = 10
local VALUE_WIDTH = 50
-- One line: label on the left 42%, a flat bar in the middle, the editable value on the right.
local LABEL_SHARE = 0.42
local TRACK_INSET = 0

return function(section: Instance, spec, ctx)
	local theme = ctx.theme
	local key = spec.key
	local function finite(value, fallback: number): number
		local numberValue = tonumber(value)
		if numberValue == nil or numberValue ~= numberValue or numberValue == math.huge or numberValue == -math.huge then
			return fallback
		end
		return numberValue
	end
	local minV = finite(spec.min, 0)
	local maxV = finite(spec.max, minV + 1)
	if maxV <= minV then
		maxV = minV + 1
	end
	local step = finite(spec.step, 1)
	if step <= 0 then
		step = 1
	end
	local decimals = math.max(Util.stepDecimals(step), Util.stepDecimals(minV))
	local suffix = tostring(spec.suffix or "")
	local itemType = spec.type == "number" and "number" or "slider"

	local defaultValue = finite(spec.default, minV)
	local value = Util.snap(finite(ctx.config[key], defaultValue), minV, maxV, step)
	ctx.config[key] = value

	local row, label = Common.row(section, theme, spec.label or key, nil, 0)
	label.Size = UDim2.new(LABEL_SHARE, -8, 1, 0)

	local Editor = P.create( "TextBox", {
		AnchorPoint = Vector2.new( 1, 0.5 ); Position = UDim2.new( 1, 0, 0.5, 0 );
		Size = UDim2.fromOffset( VALUE_WIDTH, 18 ); BackgroundColor3 = theme.control;
		BackgroundTransparency = 1; BorderSizePixel = 0; Text = ""; ClearTextOnFocus = false;
		TextColor3 = theme.textDim; Font = theme.font; TextSize = theme.textSizeSmall;
		FontFace = theme.fontFace; TextXAlignment = Enum.TextXAlignment.Right;
		Parent = row;
	} );
	P.corner( Editor, theme.cornerSmall );
	local EditorStroke = P.stroke( Editor, theme.stroke, 1, 1 );

	local track = P.create("Frame", {
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(LABEL_SHARE, TRACK_INSET, 0.5, 0),
		Size = UDim2.new(1 - LABEL_SHARE, -(TRACK_INSET * 2 + VALUE_WIDTH + 8), 0, TRACK_HEIGHT),
		BackgroundColor3 = theme.stroke,
		BorderSizePixel = 0,
		Parent = row,
	})
	local trackStroke = P.stroke(track, theme.outline or theme.stroke, 1, 0)
	P.gradient(track, Color3.new(1, 1, 1), Color3.fromRGB(175, 175, 175), 90)
	-- Black outer line plus a grey inner one, so the empty bar reads against the section card.
	local TrackInner = P.create( "Frame", {
		BackgroundTransparency = 1; BorderSizePixel = 0;
		Position = UDim2.fromOffset( 1, 1 ); Size = UDim2.new( 1, -2, 1, -2 );
		Parent = track;
	} );
	local TrackInnerStroke = P.stroke( TrackInner, theme.strokeBright or theme.stroke, 1, 0 );

	local fill = P.create("Frame", {
		BackgroundColor3 = theme.accent,
		BorderSizePixel = 0,
		Size = UDim2.fromScale(0, 1),
		Parent = track,
	})
	local fillGradient = P.gradient(fill, Color3.new(1, 1, 1), Color3.fromRGB(165, 165, 165), 90)

	local function format(v: number): string
		if decimals > 0 then
			return string.format("%." .. decimals .. "f%s", v, suffix)
		end
		return string.format("%d%s", v, suffix)
	end

	local function render(animated: boolean?)
		local alpha = (value - minV) / (maxV - minV)
		local clamped = Util.clamp(alpha, 0, 1)
		fill.Size = UDim2.fromScale(clamped, 1)
		if ( not Editor : IsFocused( ) ) then Editor.Text = format( value ); end
	end

	local control = {}

	function control.set(v: number, silent: boolean?)
		local nextValue = Util.snap(finite(v, defaultValue), minV, maxV, step)
		local changed = nextValue ~= value
		value = nextValue
		ctx.config[key] = value
		render(changed)
		if changed and not silent then
			if spec.onChange then
				Common.safeCall(ctx, "slider onChange " .. tostring(key), spec.onChange, value)
			end
			ctx.dispatch(key, value, itemType)
		end
	end

	function control.get(): number
		return value
	end
	control.setValue = control.set
	control.getValue = control.get

	render(false)
	Common.connect( ctx, Editor.Focused, function( )
		Editor.Text = tostring( value ); EditorStroke.Color = theme.accent; EditorStroke.Transparency = 0;
		Editor.BackgroundTransparency = 0; Editor.TextColor3 = theme.text;
	end );
	Common.connect( ctx, Editor.FocusLost, function( )
		local Number = tonumber( Editor.Text );
		if ( Number and Number == Number and math.abs( Number ) ~= math.huge ) then control.set( Number ); end
		Editor.Text = format( value );
		EditorStroke.Transparency = 1;
		Editor.BackgroundTransparency = 1; Editor.TextColor3 = theme.textDim;
	end );
	Common.connect( ctx, Editor.InputBegan, function( Input )
		if ( not Editor : IsFocused( ) ) then return; end
		local Direction = 0;
		if ( Input.KeyCode == Enum.KeyCode.Up ) then Direction = 1; end
		if ( Input.KeyCode == Enum.KeyCode.Down ) then Direction = -1; end
		if ( Direction == 0 ) then return; end
		local Multiplier = 1;
		if ( UserInputService : IsKeyDown( Enum.KeyCode.LeftShift ) or UserInputService : IsKeyDown( Enum.KeyCode.RightShift ) ) then Multiplier = 10; end
		control.set( finite( tonumber( Editor.Text ), value ) + Direction * step * Multiplier );
		Editor.Text = tostring( value );
	end );

	local activeInput: InputObject? = nil
	local function updateFromX(x: number)
		local absPos = track.AbsolutePosition.X
		local absSize = track.AbsoluteSize.X
		local alpha = Util.clamp((x - absPos) / math.max(absSize, 1), 0, 1)
		control.set(minV + alpha * (maxV - minV))
	end

	Common.connect(ctx, track.InputBegan, function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			if activeInput then return end
			activeInput = input
			updateFromX(input.Position.X)
		end
	end)
	local hit = P.create("TextButton", {
		BackgroundTransparency = 1,
		Text = "",
		Size = UDim2.new(1 - LABEL_SHARE, -(VALUE_WIDTH + 6), 1, 0),
		Position = UDim2.new(LABEL_SHARE, 0, 0, 0),
		Parent = row,
	}) :: TextButton
	Common.connect(ctx, hit.InputBegan, function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			if activeInput then return end
			activeInput = input
			updateFromX(input.Position.X)
		end
	end)

	ctx.maid:give(UserInputService.InputChanged:Connect(function(input)
		if not activeInput then
			return
		end
		if activeInput.UserInputType == Enum.UserInputType.Touch then
			if input == activeInput then
				updateFromX(input.Position.X)
			end
		elseif input.UserInputType == Enum.UserInputType.MouseMovement then
			updateFromX(input.Position.X)
		end
	end))
	ctx.maid:give(UserInputService.InputEnded:Connect(function(input)
		if input == activeInput then
			activeInput = nil
		end
	end))

	Common.onTheme(ctx, function()
		Editor.BackgroundColor3 = theme.control;
		Editor.TextColor3 = Editor : IsFocused( ) and theme.text or theme.textDim;
		EditorStroke.Color = theme.accent;
		track.BackgroundColor3 = theme.stroke
		trackStroke.Color = theme.outline or theme.stroke
		TrackInnerStroke.Color = theme.strokeBright or theme.stroke
		fill.BackgroundColor3 = theme.accent
		fillGradient.Color = ColorSequence.new(Color3.new(1, 1, 1), Color3.fromRGB(165, 165, 165))

	end)

	return control
end]];
		["ui/components/textbox.lua"] = [[
local P = require("ui/primitives.lua")
local Common = require("ui/components/common.lua")

return function(section: Instance, spec, ctx)
	local theme = ctx.theme
	local key = spec.key

	local initial = ctx.config[key]
	if initial == nil then
		initial = if spec.default == nil then "" else tostring(spec.default)
	else
		initial = tostring(initial)
	end
	if spec.numeric and initial ~= "" and tonumber(initial) == nil then
		initial = if tonumber(spec.default) ~= nil then tostring(tonumber(spec.default)) else ""
	end
	ctx.config[key] = initial

	local inline = spec.layout == "inline"
	local parentRow, controlSlot
	if inline then
		parentRow = Common.row(section, theme, spec.label or key, theme.rowHeight + 4, 132)
		controlSlot = parentRow
	else
		local field
		field, _, controlSlot = Common.field(section, theme, spec.label or key, theme.controlHeight or 30)
		parentRow = field
	end

	local box = P.create("TextBox", {
		Size = if inline
			then UDim2.fromOffset(132, 26)
			else UDim2.new(1, 0, 1, 0),
		AnchorPoint = if inline then Vector2.new(1, 0.5) else nil,
		Position = if inline then UDim2.new(1, 0, 0.5, 0) else UDim2.fromOffset(0, 0),
		BackgroundColor3 = theme.control or theme.surface,
		Text = initial,
		PlaceholderText = spec.placeholder or "",
		Font = theme.font,
		FontFace = theme.fontFace,
		TextSize = theme.textSizeSmall,
		TextColor3 = theme.text,
		PlaceholderColor3 = theme.textFaint,
		ClearTextOnFocus = false,
		TextXAlignment = Enum.TextXAlignment.Left,
		Parent = controlSlot,
	}) :: TextBox
	P.corner(box, theme.cornerSmall)
	local stroke = P.stroke(box, theme.stroke, 1, 0.35)
	P.paddingXY(box, 10, 0)

	local control = {}
	local focused = false
	local Hovered = false;

	local function RefreshSurface( Animated: boolean )
		local Highlighted = focused or Hovered;
		local Background = theme.control or theme.surface;
		if ( Highlighted ) then
			Background = theme.controlHover or theme.overlay;
		end
		P.tween( box, Animated and ( theme.fast or 0.1 ) or 0, { BackgroundColor3 = Background } );
		stroke.Color = theme.stroke;
		stroke.Transparency = 0.35;
		if ( Hovered ) then
			stroke.Color = theme.strokeBright;
			stroke.Transparency = 0.18;
		end
		if ( focused ) then
			stroke.Color = theme.accent;
			stroke.Transparency = 0;
		end
	end

	Common.connect( ctx, box.MouseEnter, function( )
		Hovered = true;
		RefreshSurface( true );
	end )
	Common.connect( ctx, box.MouseLeave, function( )
		Hovered = false;
		RefreshSurface( true );
	end )
	function control.get(): string
		return box.Text or ""
	end
	function control.set(text: string, silent: boolean?)
		local nextText = if text == nil then "" else tostring(text)
		if spec.numeric and nextText ~= "" then
			local numeric = tonumber(nextText)
			nextText = if numeric ~= nil then tostring(numeric)
				else (if tonumber(spec.default) ~= nil then tostring(tonumber(spec.default)) else "")
		end
		local changed = nextText ~= (box.Text or "")
		box.Text = nextText
		ctx.config[key] = nextText
		if changed and not silent then
			if spec.onChange then
				Common.safeCall(ctx, "text onChange " .. tostring(key), spec.onChange, nextText)
			end
			ctx.dispatch(key, nextText, "text")
		end
	end
	control.setValue = control.set
	control.getValue = control.get

	Common.connect(ctx, box.Focused, function()
		focused = true
		RefreshSurface( true );
	end)
	Common.connect(ctx, box.FocusLost, function()
		focused = false
		RefreshSurface( true );

		local before = tostring(ctx.config[key] or "")
		local text = box.Text or ""
		if spec.numeric then
			if text == "" then
				ctx.config[key] = ""
			else
				local n = tonumber(text)
				ctx.config[key] = n and tostring(n) or ctx.config[key]
				box.Text = ctx.config[key]
			end
		else
			ctx.config[key] = text
		end
		if ctx.config[key] == before then
			return
		end
		if spec.onChange then
			Common.safeCall(ctx, "text onChange " .. tostring(key), spec.onChange, ctx.config[key])
		end
		ctx.dispatch(key, ctx.config[key], "text")
	end)

	Common.onTheme(ctx, function()
		RefreshSurface( false );
		box.TextColor3 = theme.text
		box.PlaceholderColor3 = theme.textFaint
	end)

	return control
end]];
		["ui/components/toggle.lua"] = [[
local P = require("ui/primitives.lua")
local Common = require("ui/components/common.lua")

-- A square checkbox to the left of the label, shaded top to bottom like the classic script menus.
local BOX = 12
local LABEL_INDENT = BOX + 8

local function makeSwitch(parent: Instance, theme, state: boolean)
	local switch = P.create("Frame", {
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, 0, 0.5, 0),
		Size = UDim2.fromOffset(BOX, BOX),
		BackgroundColor3 = state and theme.accent or (theme.control or theme.surface),
		BorderSizePixel = 0,
		Parent = parent,
	})
	P.corner(switch, 2)
	local stroke = P.stroke(switch, theme.outline or theme.stroke, 1, 0)
	local shade = P.gradient(switch, Color3.new(1, 1, 1), Color3.fromRGB(165, 165, 165), 90)
	return switch, stroke, shade
end

return function(section: Instance, spec, ctx)
	local theme = ctx.theme
	local key = spec.key
	local rawState = ctx.config[key]
	local state = if rawState == nil then spec.default == true else rawState == true
	ctx.config[key] = state

	if spec.hud then
		ctx.registerHud(key, tostring(spec.hud))
	end

	local host = section
	local label = nil
	local clickParent = section
	if not spec.inline then
		local row, rowLabel = Common.row(section, theme, spec.label or key, nil, 0)
		rowLabel.Position = UDim2.fromOffset(LABEL_INDENT, 0)
		rowLabel.Size = UDim2.new(1, -LABEL_INDENT, 1, 0)
		host = row
		clickParent = row
		label = rowLabel
	end

	local switch, stroke, shade = makeSwitch(host, theme, state)
	if spec.inline then
		switch.AnchorPoint = Vector2.new(0.5, 0.5)
		switch.Position = UDim2.fromScale(0.5, 0.5)
	end

	local btn = P.create("TextButton", {
		BackgroundTransparency = 1,
		Text = "",
		Size = UDim2.fromScale(1, 1),
		Parent = clickParent,
	}) :: TextButton

	local hovered = false
	local control = {}

	local function render(animated: boolean)
		local time = animated and (theme.normal or 0.14) or 0
		P.tween(switch, time, {
			BackgroundColor3 = state and theme.accent or (hovered and (theme.controlHover or theme.overlay) or (theme.control or theme.surface)),
		})
		stroke.Color = hovered and theme.strokeBright or (theme.outline or theme.stroke)
		stroke.Transparency = 0

		if label then
			label.TextColor3 = state and theme.text or theme.textDim
		end
	end

	function control.set(value: boolean, silent: boolean?)
		local nextState = value == true
		local changed = nextState ~= state
		state = nextState
		ctx.config[key] = state
		render(changed)
		if changed and not silent then
			if spec.onChange then
				Common.safeCall(ctx, "toggle onChange " .. tostring(key), spec.onChange, state)
			end
			ctx.dispatch(key, state, "toggle")
		end
	end

	function control.get(): boolean
		return state
	end
	control.setValue = control.set
	control.getValue = control.get

	Common.connect(ctx, btn.MouseEnter, function()
		hovered = true
		if not spec.inline then
			P.tween(host, theme.fast or 0.1, { BackgroundTransparency = 0.55 })
		end
		render(true)
	end)
	Common.connect(ctx, btn.MouseLeave, function()
		hovered = false
		if not spec.inline then
			P.tween(host, theme.fast or 0.1, { BackgroundTransparency = 1 })
		end
		render(true)
	end)
	Common.connect(ctx, btn.MouseButton1Click, function()
		control.set(not state)
	end)

	render(false)
	Common.onTheme(ctx, function()
		render(false)
	end)

	return control
end]];
		["ui/feature-index.lua"] = [[
-- Cache
local Lower = string.lower;
local Find = string.find;
local M = { };
local Aliases = { dropdown = "select", multiselect = "select", textbox = "text", input = "text" };
local Supported = { toggle = true, slider = true, number = true, select = true, color = true, text = true, keybind = true, button = true };

function M.collect( Pages: { any } ): { any }
	local Entries, Seen = { }, { };
	local function Visit( Items: { any }, Page: any, Section: any, Path: string, Ancestors: { any } )
		for _, Item in Items do
			local Label = tostring( Item.label or Item.key or "" );
			local Kind = Item.type;
			local Control = Item;
			if ( Kind == "group" or Kind == "collapsible" ) then
				Control = table.clone( Item.toggleSpec or { } );
				Control.type = "toggle";
				Control.key = Item.toggleKey or Item.key;
				Control.label = Control.label or Label;
				Control.inline = false;
			elseif ( Aliases[ Kind ] ) then
				Control = table.clone( Item );
				Control.type = Aliases[ Kind ];
			end
			local Key = Control.key;
			local Id = Key or ( Control.type == "button" and Path .. "/" .. Label );
			if ( Supported[ Control.type ] and Id and not Seen[ Id ] and Label ~= "" ) then
				Seen[ Id ] = true;
				Entries[ #Entries + 1 ] = {
					id = Id; key = Key; label = Label; spec = Control;
					path = Path .. " / " .. Label; page = Page; section = Section;
					ancestors = table.clone( Ancestors );
					search = Lower( Path .. " " .. Label .. " " .. tostring( Key or "" ) );
				};
			end
			local Nested = table.clone( Ancestors );
			Nested[ #Nested + 1 ] = { spec = Item };
			if ( Item.items ) then
				Visit( Item.items, Page, Section, Path .. " / " .. Label, Nested );
			end
			for _, Profile in Item.profiles or { } do
				local ProfilePath = table.clone( Ancestors );
				ProfilePath[ #ProfilePath + 1 ] = { spec = Item, profile = Profile.label };
				Visit( Profile.items or { }, Page, Section, Path .. " / " .. Label .. " / " .. Profile.label, ProfilePath );
			end
		end
	end
	for _, Page in Pages do
		for _, Section in Page.sections or { } do
			Visit( Section.items or { }, Page, Section, Page.label .. " / " .. tostring( Section.title or "General" ), { } );
		end
	end
	return Entries;
end

function M.matches( Entry: any, Query: string ): boolean
	for Token in Lower( Query ) : gmatch( "%S+" ) do
		if ( not Find( Entry.search, Token, 1, true ) ) then
			return false;
		end
	end
	return true;
end

return M;]];
		["ui/fonts.lua"] = [[
local Theme = require("ui/theme.lua")

local Fonts = {}

function Fonts.apply(label: TextLabel | TextButton | TextBox, weight: string?, themeOverride: { [string]: any }?)
	if typeof(label) ~= "Instance" or not (label:IsA("TextLabel") or label:IsA("TextButton") or label:IsA("TextBox")) then
		return false
	end
	local theme = themeOverride or Theme.get()
	weight = if typeof(weight) == "string" then string.lower(weight) else weight
	local font = theme.font
	local fontFace = theme.fontFace

	if weight == "bold" then
		font = theme.fontBold or font
		fontFace = theme.fontFaceBold or fontFace
	elseif weight == "medium" then
		font = theme.fontMedium or font
		fontFace = theme.fontFaceMedium or fontFace
	end

	label.Font = font
	if fontFace then
		pcall(function()
			local target = label :: any
			target.FontFace = fontFace
		end)
	end
	return true
end

return Fonts]];
		["ui/hud.lua"] = [[
local Services = require("core/services.lua")
local Runtime = require("core/runtime.lua")
local Theme = require("ui/theme.lua")
local P = require("ui/primitives.lua")

local TextService = Services.TextService

local Hud = {}
Hud.__index = Hud

local ROW_HEIGHT = 22
local ROW_GAP = 2
local RIGHT_MARGIN = 12
local TOP_MARGIN = 12
local CONTAINER_WIDTH = 320
local ENTRY_TEXT_SIZE = 13

local DISPLAY_ORDER = 2000000000

local function trim(value: any): string
	return (tostring(value or ""):match("^%s*(.-)%s*$")) or ""
end

local function colorForIndex(theme, index: number, total: number): Color3
	local top = theme.accent
	local bottom = theme.accentBright or theme.accent
	if total <= 1 then
		return top
	end
	return top:Lerp(bottom, (index - 1) / (total - 1))
end

local function measureWidth(text: string, font: Enum.Font, size: number): number
	local ok, bounds = pcall(function()
		return TextService:GetTextSize(text, size, font, Vector2.new(1000, 40))
	end)
	if ok and typeof(bounds) == "Vector2" then
		return bounds.X
	end
	return #text * (size * 0.55)
end

local function sortedLabels(labels, theme)
	local font = Enum.Font.SourceSansSemibold
	local seen = {}
	local entries = {}
	for _, rawLabel in (if typeof(labels) == "table" then labels else {}) do
		local text = trim(rawLabel)
		local key = string.lower(text)
		if text ~= "" and not seen[key] then
			seen[key] = true
			table.insert(entries, {
				key = key,
				text = text,
				width = measureWidth(text, font, ENTRY_TEXT_SIZE),
			})
		end
	end
	table.sort(entries, function(a, b)
		if math.abs(a.width - b.width) > 0.5 then
			return a.width > b.width
		end
		return a.key < b.key
	end)
	return entries
end

local function createOutlinedLabel(parent: Instance, text: string, props: { [string]: any })
	local holder = P.create("Frame", {
		Size = props.Size,
		BackgroundTransparency = 1,
		LayoutOrder = props.LayoutOrder or 0,
		Visible = props.Visible ~= false,
		Parent = parent,
	})

	local content = P.create("Frame", {
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, props.EnterOffset or 0, 0, 0),
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		Parent = holder,
	})

	local initialTransparency = tonumber(props.InitialTransparency) or 0

	local foreground = P.label(content, text, {
		Theme = props.Theme,
		Size = UDim2.new(1, -12, 1, 0),
		TextTruncate = Enum.TextTruncate.AtEnd,
		AutomaticSize = Enum.AutomaticSize.None,
		TextXAlignment = props.TextXAlignment,
		TextYAlignment = props.TextYAlignment,
		TextColor3 = props.TextColor3,
		TextTransparency = initialTransparency,
		Font = props.Font,
		TextSize = props.TextSize,
		TextStrokeTransparency = 0.65 + initialTransparency * 0.35,
		TextStrokeColor3 = Color3.new(0, 0, 0),
		ZIndex = 2,
	})

	local Marker = P.create( "Frame", {
		AnchorPoint = Vector2.new( 1, 0.5 ),
		Position = UDim2.new( 1, -1, 0.5, 0 ),
		Size = UDim2.fromOffset( 3, 3 ),
		BackgroundColor3 = props.TextColor3,
		BackgroundTransparency = initialTransparency,
		BorderSizePixel = 0,
		Visible = props.ShowMarker == true,
		Parent = content,
	} );
	P.corner( Marker, 2 );

	local api = {
		holder = holder,
		content = content,
		fg = foreground,
	}

	function api.setText(newText: string)
		foreground.Text = newText

	end

	function api.setVisible(visible: boolean)
		holder.Visible = visible
	end

	function api.setColor(color: Color3)
		foreground.TextColor3 = color
		Marker.BackgroundColor3 = color;
	end

	function api.tweenTransparency(transparency: number, duration: number)
		P.tween(foreground, duration, {
			TextTransparency = transparency,
			TextStrokeTransparency = 0.65 + transparency * 0.35,
		})
		P.tween( Marker, duration, { BackgroundTransparency = transparency } );
	end

	return api
end

function Hud.new(title: string, themeOverride: { [string]: any }?)
	local theme = themeOverride or Theme.get()
	title = trim(title)
	if title == "" then
		title = Theme.brandName
	end
	local self = setmetatable({
		theme = theme,
		title = title,
		rows = {},
		rowsByKey = {},
		_signature = nil,
	}, Hud)

	local screen = P.create("ScreenGui", {
		Name = "\0",
		ResetOnSpawn = false,
		IgnoreGuiInset = true,
		Enabled = false,
		ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
		DisplayOrder = DISPLAY_ORDER,
	})
	if not Runtime.setGuiParent(screen) then
		screen:Destroy()
		error("[Hub][UI] no available GUI parent for HUD")
	end
	self.screen = screen

	local container = P.create("Frame", {
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, -RIGHT_MARGIN, 0, TOP_MARGIN),
		Size = UDim2.new(0, CONTAINER_WIDTH, 0, ROW_HEIGHT),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Parent = screen,
	})
	self.container = container
	self.containerScale = P.create("UIScale", { Scale = 1, Parent = container })
	P.listLayout(container, ROW_GAP)

	self.titleRow = createOutlinedLabel(container, title, {
		Theme = theme,
		Size = UDim2.new(1, 0, 0, ROW_HEIGHT),
		TextXAlignment = Enum.TextXAlignment.Right,
		TextYAlignment = Enum.TextYAlignment.Center,
		TextColor3 = theme.text,
		Font = theme.fontBold,
		TextSize = 14,
		LayoutOrder = 0,
		Visible = false,
	})

	self.statusRow = createOutlinedLabel(container, "idle", {
		Theme = theme,
		Size = UDim2.new(1, 0, 0, ROW_HEIGHT),
		TextXAlignment = Enum.TextXAlignment.Right,
		TextYAlignment = Enum.TextYAlignment.Center,
		TextColor3 = theme.textFaint,
		Font = theme.fontBold,
		TextSize = ENTRY_TEXT_SIZE,
		LayoutOrder = 1,
		Visible = false,
	})

	return self
end

function Hud:_createRow(entry, index: number, total: number)
	local theme = self.theme
	local row = createOutlinedLabel(self.container, entry.text, {
		Theme = theme,
		Size = UDim2.new(1, 0, 0, ROW_HEIGHT),
		TextXAlignment = Enum.TextXAlignment.Right,
		TextYAlignment = Enum.TextYAlignment.Center,
		TextColor3 = colorForIndex(theme, index, total),
		ShowMarker = true,
		Font = theme.fontMedium or theme.font,
		TextSize = ENTRY_TEXT_SIZE,
		LayoutOrder = index + 1,
		InitialTransparency = 1,
		EnterOffset = 10,
	})
	row.key = entry.key
	row.removing = false
	P.tween(row.content, theme.normal or 0.1, { Position = UDim2.fromScale(1, 0) }, Enum.EasingStyle.Quint)
	row.tweenTransparency(0, theme.normal or 0.1)
	return row
end

function Hud:_removeRow(row)
	if row.removing then
		return
	end
	row.removing = true
	row.holder.LayoutOrder = 10000
	local duration = self.theme.normal or 0.1
	P.tween(row.content, duration, { Position = UDim2.new(1, 12, 0, 0) }, Enum.EasingStyle.Quint)
	row.tweenTransparency(1, duration)
	task.delay(duration + 0.03, function()
		if row.holder and row.holder.Parent then
			row.holder:Destroy()
		end
	end)
end

function Hud:setVisible(visible: boolean)
	if not self.screen then
		return
	end
	local show = visible == true
	if show and not self.screen.Enabled then
		self.screen.Enabled = true
		self.containerScale.Scale = 1
		P.tween(self.containerScale, self.theme.normal or 0.1, { Scale = 1 }, Enum.EasingStyle.Quint)
	elseif not show then
		self.screen.Enabled = false
	end
end

function Hud:setActive(labels: { string })
	if not self.screen then
		return
	end
	local entries = sortedLabels(labels, self.theme)
	local signatureParts = {}
	local nextKeys = {}
	for _, entry in entries do
		table.insert(signatureParts, entry.key .. "=" .. entry.text)
		nextKeys[entry.key] = true
	end
	local signature = table.concat(signatureParts, "\0")
	if signature == self._signature then
		return
	end
	self._signature = signature

	for key, row in self.rowsByKey do
		if not nextKeys[key] then
			self.rowsByKey[key] = nil
			self:_removeRow(row)
		end
	end

	local orderedRows = {}
	for index, entry in entries do
		local row = self.rowsByKey[entry.key]
		if not row then
			row = self:_createRow(entry, index, #entries)
			self.rowsByKey[entry.key] = row
		else
			row.setText(entry.text)
			row.holder.LayoutOrder = index + 1
			row.setColor(colorForIndex(self.theme, index, #entries))
		end
		table.insert(orderedRows, row)
	end
	self.rows = orderedRows

	local active = #entries > 0
	self.titleRow.setText( self.title .. "  /  " .. tostring( #entries ) );
	self.titleRow.setVisible(active)
	self.statusRow.setVisible(not active)
	if not active then
		self.statusRow.setText("idle")
	end
end

function Hud:refreshTheme()
	if not self.screen then
		return
	end
	local theme = self.theme
	self.titleRow.setColor(theme.text)
	self.statusRow.setColor(theme.textFaint)
	for index, row in self.rows do
		row.setColor(colorForIndex(theme, index, #self.rows))
	end
end

function Hud:destroy()
	if self._destroyed then
		return
	end
	self._destroyed = true
	if self.screen then
		self.screen:Destroy()
		self.screen = nil
	end
	table.clear(self.rows)
	table.clear(self.rowsByKey)
end

return Hud]];
