		["ui/notify.lua"] = [[
local Runtime = require("core/runtime.lua")
local Theme = require("ui/theme.lua")
local Icons = require("ui/icons.lua")
local P = require("ui/primitives.lua")

local Notify = {}

local container = nil
local screen = nil
local activeCards = {}
local expiryTasks = {}
local HOST_ATTRIBUTE = "MicroHubNotificationHostV1"
local cleanupScheduled = false

local function scheduleHostCleanup()
	if cleanupScheduled then
		return
	end
	cleanupScheduled = true
	task.defer(function()
		cleanupScheduled = false
		if #activeCards ~= 0 then
			return
		end
		local host = screen
		container = nil
		screen = nil
		if host and host.Parent then
			host:Destroy()
		end
	end)
end

local function looksLikeNotificationScreen(screen: Instance): boolean
	return screen:IsA("ScreenGui") and screen:GetAttribute(HOST_ATTRIBUTE) == true
end

local function ensureContainer()
	if container and container.Parent then
		return container
	end
	local ok, children = pcall(function()
		return Runtime.withExecutorIdentity(function()
			return Runtime.gui():GetChildren()
		end)
	end)
	if ok then
		for _, child in children do
			if looksLikeNotificationScreen(child) then
				pcall(function() child:Destroy() end)
			end
		end
	end
	screen = P.create("ScreenGui", {
		Name = "\0",
		ResetOnSpawn = false,
		IgnoreGuiInset = true,
		DisplayOrder = 1001,
	})
	screen:SetAttribute(HOST_ATTRIBUTE, true)
	if not Runtime.setGuiParent(screen) then
		screen:Destroy()
		screen = nil
		return nil
	end
	local holder = P.create("Frame", {
		AnchorPoint = Vector2.new(1, 1),
		Position = UDim2.new(1, -20, 1, -20),
		Size = UDim2.new(1, -40, 1, -40),
		BackgroundTransparency = 1,
		Parent = screen,
	})
	P.create("UISizeConstraint", {
		MaxSize = Vector2.new(320, 440),
		MinSize = Vector2.new(180, 0),
		Parent = holder,
	})
	local layout = P.listLayout(holder, 8)
	layout.VerticalAlignment = Enum.VerticalAlignment.Bottom
	layout.HorizontalAlignment = Enum.HorizontalAlignment.Right
	container = holder
	return holder
end

function Notify.push(arg, duration: number?, color: Color3?)
	local theme = Theme.get()
	local title, text, dur, accent, iconName
	if typeof(arg) == "table" then
		title, text = arg.title, arg.text
		dur = arg.duration or 3
		accent = arg.color or theme.accent
		iconName = arg.icon
	else
		if arg == nil then
			return nil
		end
		text = tostring(arg)
		dur = duration or 3
		accent = color or theme.accent
	end
	if iconName == nil then
		iconName = title and "bell" or "info"
	end
	if text == nil or tostring(text) == "" then
		return nil
	end
	title = if title ~= nil and tostring(title) ~= "" then tostring(title) else nil
	text = tostring(text)
	dur = tonumber(dur) or 3
	if dur ~= dur or dur == math.huge or dur == -math.huge then
		dur = 3
	end
	dur = math.clamp(dur, 0.1, 60)
	if typeof(accent) ~= "Color3" then
		accent = theme.accent
	end

	local holder = ensureContainer()
	if not holder then
		return nil
	end
	local card = P.create("Frame", {
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundColor3 = theme.surface or theme.panel,
		BackgroundTransparency = 0.04,
		BorderSizePixel = 0,
		ClipsDescendants = true,
		Parent = holder,
	})
	table.insert(activeCards, card)
	card.Destroying:Connect(function()
		local expiryThread = expiryTasks[card]
		if expiryThread then
			pcall(task.cancel, expiryThread)
			expiryTasks[card] = nil
		end
		local index = table.find(activeCards, card)
		if index then
			table.remove(activeCards, index)
		end
		scheduleHostCleanup()
	end)
	P.corner(card, theme.cornerSmall)
	P.stroke(card, theme.stroke, 1, 0)

	P.create("Frame", {
		Size = UDim2.new(0, 2, 1, 0),
		BackgroundColor3 = accent,
		BorderSizePixel = 0,
		Parent = card,
	})

	local body = P.create("Frame", {
		Position = UDim2.fromOffset(3, 0),
		Size = UDim2.new(1, -3, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Parent = card,
	})
	P.paddingXY(body, 10, 7)

	local contentRow = P.create("Frame", {
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Parent = body,
	})
	P.listLayout(contentRow, 8, Enum.FillDirection.Horizontal)

	local iconBadge = P.create("Frame", {
		Size = UDim2.fromOffset(24, 24),
		BackgroundColor3 = accent,
		BackgroundTransparency = 0.86,
		BorderSizePixel = 0,
		Parent = contentRow,
	})
	P.corner(iconBadge, theme.cornerSmall)
	Icons.mount(iconBadge, iconName, {
		size = 13,
		color = accent,
		anchorPoint = Vector2.new(0.5, 0.5),
		position = UDim2.fromScale(0.5, 0.5),
	})

	local textCol = P.create("Frame", {
		Size = UDim2.new(1, -32, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Parent = contentRow,
	})
	P.listLayout(textCol, 3)

	if title then
		P.label(textCol, title, {
			Theme = theme,
			Size = UDim2.new(1, 0, 0, 14),
			TextColor3 = theme.text,
			Font = theme.fontMedium,
			TextSize = theme.textSizeSmall,
		})
	end
	P.label(textCol, text, {
		Theme = theme,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		TextWrapped = true,
		TextColor3 = theme.text,
		TextSize = theme.textSizeSmall,
		TextYAlignment = Enum.TextYAlignment.Top,
	})

	local progress = P.create("Frame", {
		AnchorPoint = Vector2.new(0, 1),
		Position = UDim2.fromScale(0, 1),
		Size = UDim2.new(1, 0, 0, 2),
		BackgroundColor3 = theme.strokeFaint,
		BorderSizePixel = 0,
		Parent = card,
	})
	local progressFill = P.create("Frame", {
		Size = UDim2.fromScale(1, 1),
		BackgroundColor3 = accent,
		BorderSizePixel = 0,
		Parent = progress,
	})
	card.Position = UDim2.new(1, 32, 0, 0)
	card.BackgroundTransparency = 1
	P.tween(card, theme.normal, {
		Position = UDim2.new(0, 0, 0, 0),
		BackgroundTransparency = 0.04,
	})
	P.tween(progressFill, dur, { Size = UDim2.fromScale(0, 1) })

	local expiryThread
	expiryThread = task.delay(dur, function()
		expiryTasks[card] = nil
		if card.Parent then
			P.tween(card, theme.normal, { BackgroundTransparency = 1, Position = UDim2.new(1, 36, 0, 0) })
			task.wait(theme.normal)
			card:Destroy()
		end
		local index = table.find(activeCards, card)
		if index then
			table.remove(activeCards, index)
		end
	end)
	expiryTasks[card] = expiryThread

	return card
end

function Notify.dismiss(card: Instance)
	if typeof(card) ~= "Instance" then
		return
	end
	local expiryThread = expiryTasks[card]
	if expiryThread then
		pcall(task.cancel, expiryThread)
		expiryTasks[card] = nil
	end
	local index = table.find(activeCards, card)
	if index then
		table.remove(activeCards, index)
	end
	if card.Parent then
		card:Destroy()
	end
	scheduleHostCleanup()
end

function Notify.destroy()
	for _, expiryThread in expiryTasks do
		pcall(task.cancel, expiryThread)
	end
	table.clear(expiryTasks)
	for _, card in activeCards do
		if card.Parent then
			card:Destroy()
		end
	end
	table.clear(activeCards)
	if container then
		local parentScreen = container:FindFirstAncestorOfClass("ScreenGui")
		if parentScreen then
			parentScreen:Destroy()
		else
			container:Destroy()
		end
		container = nil
	end
	if screen then
		if screen.Parent then
			screen:Destroy()
		end
		screen = nil
	end
	local ok, children = pcall(function()
		return Runtime.withExecutorIdentity(function()
			return Runtime.gui():GetChildren()
		end)
	end)
	if not ok then
		return
	end
	for _, child in children do
		if looksLikeNotificationScreen(child) then
			pcall(function()
				child:Destroy()
			end)
		end
	end
end

return Notify]];
		["ui/organize.lua"] = [[
-- Orders a menu's pages and each page's sections by category, so every game's menu reads the same way:
-- overview, combat, visuals, movement, player, world and automation, then misc. A label's category comes
-- from the words in it ("Silent Aim" is combat, "Teleports" is world). Labels with no known word sit
-- between world and misc. Items inside a section never move.
--
-- A page or section with a numeric `order` uses it as its rank instead (the ranks below run 0 to 7), and
-- `Hub.UI.create{ organize = false }` turns ordering off. Ties keep their declared order.

-- Cache
local StringLower = string.lower;
local StringFind = string.find;
local TableSort = table.sort;
local TypeOf = typeof;
local ToString = tostring;

-- Constants
local UNKNOWN_RANK = 6;

-- Each word matches at the start of a word in the label: "aim" matches "Aimbot" and "Anti Aim".
local CATEGORIES = {
	{ Rank = 0, Words = { "main", "home", "dashboard", "overview", "general", "info", "status" } };
	{ Rank = 1, Words = { "combat", "aim", "silent", "rage", "legit", "trigger", "weapon", "gun", "kill", "attack", "fight", "pvp", "hitbox", "melee", "parry", "block" } };
	{ Rank = 2, Words = { "visual", "esp", "chams", "render", "radar", "crosshair", "tracer", "highlight", "camera", "view", "spectate" } };
	{ Rank = 3, Words = { "movement", "move", "speed", "fly", "jump", "noclip", "walk", "dash" } };
	{ Rank = 4, Words = { "player", "character", "self", "local", "humanoid" } };
	{ Rank = 5, Words = { "world", "farm", "auto", "harvest", "garden", "plant", "economy", "shop", "sell", "store", "teleport", "map", "server", "quest", "pet", "event", "upgrade", "tool", "crate", "item", "loot" } };
	{ Rank = 7, Words = { "misc", "other", "extra", "fun", "troll", "util", "credit", "stat" } };
};

-- Types
type Entry = { [ string ]: any };

-- Main
local Organize = { }; do
	function Organize.Rank( Label: any ): number
		if ( TypeOf( Label ) ~= "string" ) then
			return UNKNOWN_RANK;
		end

		local Lower = StringLower( Label );

		for _, Category in CATEGORIES do
			for _, Word in Category.Words do
				if ( StringFind( Lower, "%f[%w]" .. Word ) ) then
					return Category.Rank;
				end
			end
		end

		return UNKNOWN_RANK;
	end

	-- Stable sort of `List` in place by rank; `LabelOf` reads an entry's label.
	function Organize.Sort( List: { Entry }, LabelOf: ( Entry ) -> any )
		local Keys = { };

		for Index, Item in List do
			local Rank = TypeOf( Item ) == "table" and Item.order;

			if ( TypeOf( Rank ) ~= "number" or Rank ~= Rank ) then
				Rank = Organize.Rank( LabelOf( Item ) );
			end

			Keys[ Item ] = { Rank = Rank, Index = Index };
		end

		TableSort( List, function( Left: Entry, Right: Entry ): boolean
			local A = Keys[ Left ];
			local B = Keys[ Right ];

			if ( A.Rank ~= B.Rank ) then
				return A.Rank < B.Rank;
			end

			return A.Index < B.Index;
		end );
	end

	function Organize.Pages( Pages: { Entry } )
		Organize.Sort( Pages, function( Page: Entry ): any
			return Page.label;
		end );
	end

	function Organize.Sections( Sections: { Entry } )
		Organize.Sort( Sections, function( Section: Entry ): any
			return Section.title and ToString( Section.title ) or nil;
		end );
	end
end

return Organize;]];
		["ui/overlay.lua"] = [[
-- Screen overlays that sit outside the menu, in the classic script-menu style: a watermark bar
-- (brand, game, fps, ping, clock) and a draggable keybind list showing each bound key and whether
-- its feature is on. ui/init.lua owns the data; this module only draws it.

-- Dependencies
local Services = require( "core/services.lua" );
local Runtime = require( "core/runtime.lua" );
local P = require( "ui/primitives.lua" );

-- Services
local RunService = Services.RunService;
local UserInputService = Services.UserInputService;
local Players = Services.Players;

-- Cache
local OsClock = os.clock;
local OsDate = os.date;
local MathFloor = math.floor;
local StringFormat = string.format;
local TableConcat = table.concat;

-- Constants
local DISPLAY_ORDER = 999;
local MARGIN = 10;
local BAR_HEIGHT = 22;
local LIST_WIDTH = 190;
local LIST_HEADER = 22;
local LIST_ROW = 17;
local TICK_INTERVAL = 0.5;

-- Types
export type KeybindRow = {
	Name: string,
	Key: string,
	Active: boolean,
};

export type OverlayOptions = {
	Theme: { [string]: any },
	Brand: string,
	Game: string,
};

-- Utilities
local Box = { }; do
	-- A panel drawn the way the menu draws its window: black outer line, lighter inner line and
	-- an accent strip along the top. Callers put their content in the returned Content frame, so
	-- their layouts and padding never touch the border pieces.
	function Box.New( Parent: Instance, Theme: any ): ( Frame, ( any ) -> ( ), Frame )
		local Frame = P.create( "Frame", {
			BorderSizePixel = 0;
			Parent = Parent;
		} ) :: Frame;
		local Outer = P.stroke( Frame, Theme.outline or Theme.stroke, 1, 0 );
		local Inner = P.create( "Frame", {
			Position = UDim2.fromOffset( 1, 1 );
			Size = UDim2.new( 1, -2, 1, -2 );
			BackgroundTransparency = 1;
			ZIndex = 3;
			Parent = Frame;
		} );
		local InnerStroke = P.stroke( Inner, Theme.stroke, 1, 0 );
		local Accent = P.create( "Frame", {
			Size = UDim2.new( 1, 0, 0, 2 );
			BorderSizePixel = 0;
			BackgroundColor3 = Color3.new( 1, 1, 1 );
			ZIndex = 4;
			Parent = Frame;
		} );
		local AccentGradient = P.gradient( Accent, Theme.accent, Theme.accentSoft or Theme.accent, 0 );
		local Content = P.create( "Frame", {
			BackgroundTransparency = 1;
			ZIndex = 5;
			Parent = Frame;
		} ) :: Frame;

		local function Paint( Colors: any )
			Frame.BackgroundColor3 = Colors.panel or Colors.background;
			Outer.Color = Colors.outline or Colors.stroke;
			InnerStroke.Color = Colors.stroke;
			AccentGradient.Color = ColorSequence.new( Colors.accent, Colors.accentSoft or Colors.accent );
		end

		Paint( Theme );
		return Frame, Paint, Content;
	end
end

local function ReadPing( ): number?
	local LocalPlayer = Players and Players.LocalPlayer;

	if ( not LocalPlayer ) then
		return nil;
	end

	local Ok, Seconds = pcall( LocalPlayer.GetNetworkPing, LocalPlayer );

	if ( not Ok or typeof( Seconds ) ~= "number" ) then
		return nil;
	end

	return Seconds * 1000;
end

local function EscapeRich( Text: string ): string
	return ( string.gsub( string.gsub( string.gsub( Text, "&", "&amp;" ), "<", "&lt;" ), ">", "&gt;" ) );
end

local function Hex( Color: Color3 ): string
	return StringFormat( "#%02X%02X%02X", MathFloor( Color.R * 255 + 0.5 ), MathFloor( Color.G * 255 + 0.5 ), MathFloor( Color.B * 255 + 0.5 ) );
end

-- Classes
local Overlay = { }; do
	Overlay.__index = Overlay;

	function Overlay.New( Options: OverlayOptions ): any
		local Theme = Options.Theme;
		local Self = setmetatable( {
			Theme = Theme;
			Brand = string.lower( Options.Brand or "" );
			Game = string.lower( Options.Game or "" );
			Painters = { };
			Connections = { };
			Rows = { };
			Binds = { };
			Signature = nil;
			WatermarkWanted = false;
			KeybindsWanted = false;
			Fps = 0;
			Destroyed = false;
		}, Overlay );

		local Screen = P.create( "ScreenGui", {
			Name = "\0";
			ResetOnSpawn = false;
			IgnoreGuiInset = false;
			ZIndexBehavior = Enum.ZIndexBehavior.Sibling;
			DisplayOrder = DISPLAY_ORDER;
		} );

		if ( not Runtime.setGuiParent( Screen ) ) then
			Screen : Destroy( );
			error( "[Hub][UI] no available GUI parent for overlay" );
		end

		Self.Screen = Screen;
		Self : _BuildWatermark( );
		Self : _BuildKeybinds( );
		Self : _StartTicker( );
		Self : RefreshTheme( );
		return Self;
	end

	function Overlay : _Give( Connection: RBXScriptConnection ): RBXScriptConnection
		table.insert( self.Connections, Connection );
		return Connection;
	end

	function Overlay : _BuildWatermark( )
		local Theme = self.Theme;
		local Bar, Paint, Content = Box.New( self.Screen, Theme );
		Bar.Position = UDim2.fromOffset( MARGIN, MARGIN );
		Bar.Size = UDim2.fromOffset( 0, BAR_HEIGHT );
		Bar.AutomaticSize = Enum.AutomaticSize.X;
		Bar.Visible = false;
		Content.Size = UDim2.new( 0, 0, 1, 0 );
		Content.AutomaticSize = Enum.AutomaticSize.X;
		P.paddingXY( Content, 8, 0 );

		local Text = P.label( Content, "", {
			Theme = Theme;
			AutomaticSize = Enum.AutomaticSize.X;
			Size = UDim2.new( 0, 0, 1, 0 );
			RichText = true;
			TextSize = Theme.textSizeSmall;
			ZIndex = 5;
		} );

		self.Watermark = Bar;
		self.WatermarkText = Text;
		table.insert( self.Painters, function( Colors: any )
			Paint( Colors );
			Text.TextColor3 = Colors.textDim;
			Text.FontFace = Colors.fontFace;
		end );
	end

	function Overlay : _BuildKeybinds( )
		local Theme = self.Theme;
		local Panel, Paint, Content = Box.New( self.Screen, Theme );
		Panel.Position = UDim2.new( 0, MARGIN, 0.35, 0 );
		Panel.Size = UDim2.fromOffset( LIST_WIDTH, 0 );
		Panel.AutomaticSize = Enum.AutomaticSize.Y;
		Panel.Visible = false;
		Content.Size = UDim2.new( 1, 0, 0, 0 );
		Content.AutomaticSize = Enum.AutomaticSize.Y;
		P.listLayout( Content, 0 );

		local Header = P.label( Content, "keybinds", {
			Theme = Theme;
			Size = UDim2.new( 1, 0, 0, LIST_HEADER );
			TextXAlignment = Enum.TextXAlignment.Center;
			TextSize = Theme.textSizeSmall;
			LayoutOrder = 0;
			ZIndex = 5;
		} );
		Header.Active = true;

		local Line = P.create( "Frame", {
			Size = UDim2.new( 1, -12, 0, 1 );
			Position = UDim2.fromOffset( 6, 0 );
			BorderSizePixel = 0;
			LayoutOrder = 1;
			ZIndex = 5;
			Parent = Content;
		} );

		local List = P.create( "Frame", {
			Size = UDim2.new( 1, 0, 0, 0 );
			AutomaticSize = Enum.AutomaticSize.Y;
			BackgroundTransparency = 1;
			LayoutOrder = 2;
			ZIndex = 5;
			Parent = Content;
		} );
		P.listLayout( List, 0 );

		local ListPadding = P.paddingXY( List, 8, 0 );
		ListPadding.PaddingTop = UDim.new( 0, 3 );
		ListPadding.PaddingBottom = UDim.new( 0, 5 );

		self.KeybindPanel = Panel;
		self.KeybindList = List;
		table.insert( self.Painters, function( Colors: any )
			Paint( Colors );
			Header.TextColor3 = Colors.text;
			Header.FontFace = Colors.fontFace;
			Line.BackgroundColor3 = Colors.stroke;
		end );

		self : _EnableDrag( Panel, Header );
	end

	function Overlay : _EnableDrag( Panel: GuiObject, Handle: GuiObject )
		local Dragging: InputObject? = nil;
		local StartInput = Vector2.zero;
		local StartPosition = Panel.Position;

		self : _Give( Handle.InputBegan : Connect( function( Input: InputObject )
			local Kind = Input.UserInputType;

			if ( Kind ~= Enum.UserInputType.MouseButton1 and Kind ~= Enum.UserInputType.Touch ) then
				return;
			end

			Dragging = Input;
			StartInput = Vector2.new( Input.Position.X, Input.Position.Y );
			StartPosition = Panel.Position;
		end ) );

		self : _Give( UserInputService.InputChanged : Connect( function( Input: InputObject )
			if ( not Dragging ) then
				return;
			end

			local Moving = Input.UserInputType == Enum.UserInputType.MouseMovement or Input == Dragging;

			if ( not Moving ) then
				return;
			end

			local Delta = Vector2.new( Input.Position.X, Input.Position.Y ) - StartInput;
			Panel.Position = UDim2.new( StartPosition.X.Scale, StartPosition.X.Offset + Delta.X, StartPosition.Y.Scale, StartPosition.Y.Offset + Delta.Y );
		end ) );

		self : _Give( UserInputService.InputEnded : Connect( function( Input: InputObject )
			if ( Input == Dragging or Input.UserInputType == Enum.UserInputType.MouseButton1 ) then
				Dragging = nil;
			end
		end ) );
	end

	function Overlay : _StartTicker( )
		local Frames = 0;
		local Since = OsClock( );

		self : _Give( RunService.Heartbeat : Connect( function( )
			Frames += 1;
			local Now = OsClock( );
			local Elapsed = Now - Since;

			if ( Elapsed < TICK_INTERVAL ) then
				return;
			end

			self.Fps = Frames / Elapsed;
			Frames = 0;
			Since = Now;

			if ( self.Watermark.Visible ) then
				self : _RenderWatermark( );
			end
		end ) );
	end

	function Overlay : _RenderWatermark( )
		local Colors = self.Theme;
		local Ping = ReadPing( );
		local Parts = { };

		if ( self.Brand ~= "" ) then
			Parts[ #Parts + 1 ] = StringFormat( '<font color="%s">%s</font>', Hex( Colors.accent ), EscapeRich( self.Brand ) );
		end

		if ( self.Game ~= "" ) then
			Parts[ #Parts + 1 ] = EscapeRich( self.Game );
		end

		Parts[ #Parts + 1 ] = StringFormat( "%d fps", MathFloor( self.Fps + 0.5 ) );
		Parts[ #Parts + 1 ] = if ( Ping ) then StringFormat( "%d ms", MathFloor( Ping + 0.5 ) ) else "-- ms";
		Parts[ #Parts + 1 ] = tostring( OsDate( "%H:%M" ) );

		local Separator = StringFormat( ' <font color="%s">|</font> ', Hex( Colors.textFaint ) );
		self.WatermarkText.Text = TableConcat( Parts, Separator );
	end

	function Overlay : _RenderKeybinds( )
		local Colors = self.Theme;

		for _, Row in self.Rows do
			Row.Frame : Destroy( );
		end

		table.clear( self.Rows );

		for Order, Bind in self.Binds do
			local Frame = P.create( "Frame", {
				Size = UDim2.new( 1, 0, 0, LIST_ROW );
				BackgroundTransparency = 1;
				LayoutOrder = Order;
				ZIndex = 5;
				Parent = self.KeybindList;
			} );
			local Name = P.label( Frame, string.lower( Bind.Name ), {
				Theme = Colors;
				Size = UDim2.new( 1, -64, 1, 0 );
				TextSize = Colors.textSizeSmall;
				TextColor3 = Bind.Active and Colors.text or Colors.textFaint;
				TextTruncate = Enum.TextTruncate.AtEnd;
				ZIndex = 6;
			} );
			local Key = P.label( Frame, "[" .. string.lower( Bind.Key ) .. "]", {
				Theme = Colors;
				AnchorPoint = Vector2.new( 1, 0 );
				Position = UDim2.fromScale( 1, 0 );
				Size = UDim2.new( 0, 64, 1, 0 );
				TextXAlignment = Enum.TextXAlignment.Right;
				TextSize = Colors.textSizeSmall;
				TextColor3 = Bind.Active and Colors.accent or Colors.textFaint;
				ZIndex = 6;
			} );
			self.Rows[ Order ] = { Frame = Frame, Name = Name, Key = Key, Active = Bind.Active };
		end

		self.KeybindPanel.Visible = self.KeybindsWanted and #self.Binds > 0;
	end

	function Overlay : SetWatermarkVisible( Visible: boolean )
		if ( self.Destroyed ) then
			return;
		end

		self.WatermarkWanted = Visible == true;
		self.Watermark.Visible = self.WatermarkWanted;

		if ( self.WatermarkWanted ) then
			self : _RenderWatermark( );
		end
	end

	function Overlay : SetKeybindsVisible( Visible: boolean )
		if ( self.Destroyed ) then
			return;
		end

		self.KeybindsWanted = Visible == true;
		self.KeybindPanel.Visible = self.KeybindsWanted and #self.Binds > 0;
	end

	-- Rebuilds only when something shown actually changed, so callers can push on every dispatch.
	function Overlay : SetKeybinds( Binds: { KeybindRow } )
		if ( self.Destroyed ) then
			return;
		end

		local Parts = { };

		for Index, Bind in Binds do
			Parts[ Index ] = Bind.Name .. "\1" .. Bind.Key .. "\1" .. tostring( Bind.Active );
		end

		local Signature = TableConcat( Parts, "\0" );

		if ( Signature == self.Signature ) then
			return;
		end

		self.Signature = Signature;
		self.Binds = Binds;
		self : _RenderKeybinds( );
	end

	function Overlay : Containers( ): { GuiObject }
		return { self.Watermark, self.KeybindPanel };
	end

	function Overlay : RefreshTheme( )
		if ( self.Destroyed ) then
			return;
		end

		for _, Painter in self.Painters do
			Painter( self.Theme );
		end

		self.Signature = nil;
		self : _RenderKeybinds( );

		if ( self.Watermark.Visible ) then
			self : _RenderWatermark( );
		end
	end

	function Overlay : Destroy( )
		if ( self.Destroyed ) then
			return;
		end

		self.Destroyed = true;

		for _, Connection in self.Connections do
			Connection : Disconnect( );
		end

		table.clear( self.Connections );
		table.clear( self.Rows );
		self.Screen : Destroy( );
	end
end

-- Main
return Overlay;]];
