	local Columns = P.create( "Frame", {
		Size = UDim2.new( 1, -6, 0, 0 );
		AutomaticSize = Enum.AutomaticSize.Y;
		BackgroundTransparency = 1;
		Parent = Scroll;
	} );
	P.listLayout( Columns, Colors.columnGap or 12, Enum.FillDirection.Horizontal );

	local Page = {
		label = Label;
		icon = IconName;
		utility = Utility;
		container = Container;
		scroll = Scroll;
		chipBar = ChipBar;
		columns = { };
		sections = { };
		singleColumn = false;
